function withStoredThemePreference(appData: AppData): AppData {
  const theme = readStoredTheme(appData.teamContext?.profile?.id);
  if (!theme || theme === appData.settings.theme) return appData;
  return {
    ...appData,
    settings: {
      ...appData.settings,
      theme,
    },
  };
}

function useBottomNavMenuStyle(
  triggerRef: React.RefObject<HTMLButtonElement | null>,
  open: boolean,
  preferredWidth: number,
): React.CSSProperties | undefined {
  const [style, setStyle] = useState<React.CSSProperties | undefined>();

  useEffect(() => {
    if (!open) return undefined;
    const animationFrame = window.requestAnimationFrame(updatePosition);

    function updatePosition() {
      if (typeof window === "undefined" || !triggerRef.current) {
        setStyle(undefined);
        return;
      }
      const viewport = window.visualViewport;
      const viewportWidth = viewport?.width ?? window.innerWidth;
      const viewportHeight = viewport?.height ?? window.innerHeight;
      const viewportLeft = viewport?.offsetLeft ?? 0;
      if (viewportWidth <= 720) {
        setStyle(undefined);
        return;
      }

      const rect = triggerRef.current.getBoundingClientRect();
      const width = Math.min(preferredWidth, viewportWidth - 24);
      const left = Math.min(
        Math.max(rect.left + rect.width / 2 - width / 2, viewportLeft + 12),
        viewportLeft + viewportWidth - width - 12,
      );
      const bottom = Math.max(viewportHeight - rect.top + 8, 78);
      setStyle({
        left,
        right: "auto",
        bottom,
        width,
      });
    }

    window.addEventListener("resize", updatePosition);
    window.addEventListener("orientationchange", updatePosition);
    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("orientationchange", updatePosition);
    };
  }, [open, preferredWidth, triggerRef]);

  return open ? style : undefined;
}

