  async function togglePublicTeamFollow(team: PublicDirectoryTeamSummary) {
    setSaveStatus("saving");
    setSaveError(null);
    try {
      const followed = isFollowingTeam(data?.profileFollows ?? [], team.id);
      const follow = !followed;
      const followResult = await supabaseAppRepository.toggleFollow({ teamId: team.id, follow });
      setData((current) => {
        if (!current) return current;
        const remaining = (current.profileFollows ?? []).filter((item) => item.teamId !== team.id);
        return {
          ...current,
          profileFollows: follow && followResult ? [followResult, ...remaining] : remaining,
        };
      });
      setSaveStatus("saved");
    } catch (error) {
      setSaveStatus("error");
      setSaveError(error instanceof Error ? error.message : "Unable to update follow.");
    }
  }

  async function togglePublicOrganizationFollow(organization: PublicDirectoryOrganizationSummary) {
    const followed = isFollowingOrganization(data?.profileFollows ?? [], organization.id);
    setSaveStatus("saving");
    setSaveError(null);
    try {
      const follow = !followed;
      const result = await supabaseAppRepository.toggleFollow({ organizationId: organization.id, follow });
      setData((current) => {
        if (!current) return current;
        const remaining = (current.profileFollows ?? []).filter((item) => item.organizationId !== organization.id);
        return {
          ...current,
          profileFollows: follow && result ? [result, ...remaining] : remaining,
        };
      });
      setSaveStatus("saved");
    } catch (error) {
      setSaveStatus("error");
      setSaveError(error instanceof Error ? error.message : "Unable to update follow.");
    }
  }

  async function toggleTeamPin(team: TeamOption, options: { forceUnpin?: boolean } = {}) {
    const pinned = isPinnedTeam(data?.profileTeamPins, team);
    const shouldPin = options.forceUnpin ? false : !pinned;
    if (!shouldPin && !pinned) return;
    if (shouldPin && pinnedTeamsFromContext(data?.teamContext, data?.profileTeamPins).length >= 3) {
      setSaveStatus("error");
      setSaveError("You can pin up to 3 teams.");
      return;
    }

    setSaveStatus("saving");
    setSaveError(null);
    try {
      const result = await supabaseAppRepository.toggleTeamPin({ teamId: team.teamId, seasonId: team.seasonId, pin: shouldPin });
      setData((current) => {
        if (!current) return current;
        const remaining = (current.profileTeamPins ?? []).filter((pin) => !profileTeamPinMatchesTeam(pin, team));
        return {
          ...current,
          profileTeamPins: shouldPin && result ? [result, ...remaining] : remaining,
        };
      });
      setSaveStatus("saved");
    } catch (error) {
      setSaveStatus("error");
      setSaveError(error instanceof Error ? error.message : "Unable to update pinned team.");
    }
  }

  async function signOut() {
    setTopAccountMenuOpen(false);
    setSidebarAccountMenuOpen(false);
    if (isLocalDevAuthBypass()) {
      const url = new URL(window.location.href);
      url.searchParams.delete(LOCAL_AUTH_BYPASS_QUERY);
      window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
      setData(null);
      setAuthState({ status: "anonymous" });
      navigateToView("home", { replace: true });
      return;
    }
    await authRepository.signOut();
    setData(null);
    setAuthState({ status: "anonymous" });
    navigateToView("home", { replace: true });
  }

  function clearPendingHittingContext() {
    setExitVelocity("");
    setExitVelocityError(null);
  }

  function updateActiveHittingStation(station: HittingSession["type"]) {
    setHittingStation(station);
    setHittingPitchTrackingMode(defaultPracticeHittingPitchMode(station));
    clearPendingHittingContext();
    replacePracticeTrackingRoutePatch({ hittingStation: station });
  }

  function updateCurrentHittingSessionSettings(update: Partial<Pick<HittingSession, "pitchTrackingMode" | "defaultPitchType" | "machinePitchType">>) {
    if (!practice || !practicePlayer) return;
    commit((current) => {
      let updated = false;
      const now = new Date().toISOString();
      return {
        ...current,
        hittingSessions: current.hittingSessions.map((session) => {
          if (
            updated
            || session.practiceId !== practice.id
            || session.hitterId !== practicePlayer.id
            || !isPracticeSessionReusable(session)
            || !(session.type === hittingStation || (hittingStation === "Machine" && isMachineHittingStation(session.type)))
          ) {
            return session;
          }
          updated = true;
          return {
            ...session,
            ...update,
            updatedAt: now,
          };
        }),
      };
    });
  }

  function changeHittingPitchTrackingMode(mode: HittingPitchTrackingMode) {
    const nextMode = isPracticeHittingPitchTypeAvailable(hittingStation) ? mode : "OFF";
    setHittingPitchTrackingMode(nextMode);
    updateCurrentHittingSessionSettings({
      pitchTrackingMode: nextMode,
      defaultPitchType: nextMode === "OFF" ? undefined : selectedPitchType,
      machinePitchType: nextMode === "OFF" ? undefined : selectedPitchType,
    });
  }

  function changeSelectedPitchType(pitchType: PitchType) {
    setSelectedPitchType(pitchType);
    if (practiceMode !== "Hitting" || !isPracticeHittingPitchTypeAvailable(hittingStation)) return;
    updateCurrentHittingSessionSettings({
      defaultPitchType: pitchType,
      machinePitchType: pitchType,
    });
  }

  function selectLiveBpPitcher(playerId: ID) {
    clearPendingHittingContext();
    setLiveBpPitcherId(playerId);
    replacePracticeTrackingRoutePatch({ liveBpPitcherId: playerId });
  }

  function selectLiveBpHitter(playerId: ID) {
    clearPendingHittingContext();
    setLiveBpHitterId(playerId);
    replacePracticeTrackingRoutePatch({ liveBpHitterId: playerId });
  }

  function changeLiveBpThrowerSource(source: LiveBpThrowerSource) {
    clearPendingHittingContext();
    setLiveBpThrowerSource(source);
    setLiveBpCount({ balls: 0, strikes: 0 });
    replacePracticeTrackingRoutePatch({ liveBpSource: source });
  }

  function parsePendingExitVelocity() {
    if (!trackExitVelocity || !exitVelocity.trim()) {
      setExitVelocityError(null);
      return undefined;
    }
    const parsed = Number(exitVelocity);
    if (!Number.isFinite(parsed) || parsed < 20 || parsed > 130) {
      setExitVelocityError("Use 20-130 mph, or leave EV blank.");
      return null;
    }
    setExitVelocityError(null);
    return parsed;
  }

  function logHitting(action: HittingEvent["action"], contactResult?: BattedBallType, contactQuality?: HittingContactQuality, direction?: Direction, sprayPoint?: ZonePoint | null, pitchType?: PitchType, pitchLocationPoint?: ZonePoint) {
    if (!practice || !practicePlayer) return;
    const exitVelocityMph = parsePendingExitVelocity();
    if (exitVelocityMph === null) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const pitchMode = resolvePracticeHittingPitchMode(hittingStation, undefined, hittingPitchTrackingMode);
      const next = ensureHittingSession(current, practice, practicePlayer.id, hittingStation, profileId, "PLAYER", {
        pitchTrackingMode: pitchMode,
        defaultPitchType: pitchMode === "OFF" ? undefined : pitchType ?? selectedPitchType,
        machineVelocity: isMachineHittingStation(hittingStation) && velocity ? Number(velocity) : undefined,
      });
      const session = next.session;
      const eventNumber = next.data.hittingEvents.filter((event) => event.sessionId === session.id).length + 1;
      const isBip = action === "Ball in play";
      const captureSpray = trackSprayChart && isBip;
      const resolvedFieldLocation = captureSpray ? sprayPoint ?? undefined : undefined;
      const resolvedDirection = resolvedFieldLocation ? direction ?? deriveHitDirectionFromFieldLocation(resolvedFieldLocation, practicePlayer.bats) : undefined;
      const sessionPitchMode = resolvePracticeHittingPitchMode(hittingStation, session, hittingPitchTrackingMode);
      const resolvedPitchType = sessionPitchMode === "OFF" ? undefined : pitchType ?? resolvePracticeHittingPitchType(session, selectedPitchType);
      const eventId = createId("he");
      const createdAt = new Date().toISOString();
      const event: HittingEvent = {
        id: eventId,
        practiceId: practice.id,
        sessionId: session.id,
        hitterId: practicePlayer.id,
        eventNumber,
        action,
        contactResult: isBip ? contactResult : undefined,
        contactQuality: isBip ? contactQuality : undefined,
        direction: resolvedDirection,
        fieldLocation: resolvedFieldLocation,
        pitchLocation: trackHittingPitchLocation ? pitchLocationPoint : undefined,
        pitchType: resolvedPitchType,
        velocity: isMachineHittingStation(hittingStation) && velocity ? Number(velocity) : undefined,
        exitVelocityMph,
        isLiveBp: hittingStation === "Live BP",
        createdAt,
        createdByProfileId: profileId,
        entrySource: "COACH",
        verificationStatus: "COACH_RECORDED",
        idempotencyKey: eventId,
        sessionSequence: nextSessionSequence(next.data.hittingEvents, session.id),
      };
      return touchRecentPlayers({ ...next.data, hittingEvents: [event, ...next.data.hittingEvents] }, practicePlayer.id);
    });
    clearPendingHittingContext();
  }

  function updateHittingEvent(
    eventId: ID,
    update: {
      action: HittingEvent["action"];
      contactResult?: BattedBallType;
      contactQuality?: HittingContactQuality;
      direction?: Direction;
      fieldLocation?: ZonePoint;
      pitchLocation?: ZonePoint;
      exitVelocityMph?: number;
      pitchType?: PitchType;
      velocity?: number;
    },
  ) {
    if (!practice) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const updatedAt = new Date().toISOString();
      let updatedSessionId: ID | undefined;
      const hittingEvents = current.hittingEvents.map((event) => {
        if (event.id !== eventId || event.practiceId !== practice.id) return event;
        updatedSessionId = event.sessionId;
        return {
          ...event,
          action: update.action,
          contactResult: update.action === "Ball in play" ? update.contactResult : undefined,
          contactQuality: update.action === "Ball in play" ? update.contactQuality : undefined,
          direction: update.action === "Ball in play" ? update.direction : undefined,
          fieldLocation: update.action === "Ball in play" ? update.fieldLocation : undefined,
          pitchLocation: update.pitchLocation,
          exitVelocityMph: update.exitVelocityMph,
          pitchType: update.pitchType,
          velocity: update.velocity,
          updatedByProfileId: profileId,
        };
      });
      if (!updatedSessionId) return current;
      return {
        ...current,
        hittingEvents,
        hittingSessions: current.hittingSessions.map((session) =>
          session.id === updatedSessionId ? { ...session, updatedAt } : session,
        ),
      };
    });
    clearPendingHittingContext();
  }

  function logPitch(outcome: PitchOutcome, battedBall?: BattedBallType, options: PitchLogOptions = {}) {
    if (!practice || !practicePlayer) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const next = ensurePitchingSession(current, practice, practicePlayer.id, pitchingStation, profileId);
      const session = next.session;
      const sessionEvents = next.data.pitchEvents.filter((event) => event.sessionId === session.id);
      const last = sessionEvents[0];
      const resolvedLocation = options.location ?? pitchLocation;
      const resolvedTarget = options.targetLocation ?? targetLocation;
      const resolvedPitchType = options.pitchType ?? selectedPitchType;
      const isBip = outcome === "Ball in play";
      const isSwing = ["Swing", "Whiff", "Foul", "Ball in play"].includes(outcome);
      const isStrike = outcome !== "Ball" && outcome !== "HBP";
      const isZone = isPitchLocationInZone(resolvedLocation);
      const countBefore = last?.countAfter ?? { balls: 0, strikes: 0 };
      const countAfter = nextCount(countBefore, outcome);
      const eventId = createId("pe");
      const createdAt = new Date().toISOString();
      const event: PitchEvent = {
        id: eventId,
        practiceId: practice.id,
        sessionId: session.id,
        pitcherId: practicePlayer.id,
        pitchNumber: sessionEvents.length + 1,
        pitchType: resolvedPitchType,
        outcome,
        isStrike,
        isSwing,
        isZone,
        isChase: resolvedLocation ? isSwing && !isZone : undefined,
        isWhiff: outcome === "Whiff",
        isCalledStrike: outcome === "Called Strike",
        isBallInPlay: isBip,
        battedBall: isBip ? battedBall : undefined,
        contactQuality: isBip ? (battedBall === "Line drive" ? "Hard contact" : "Medium contact") : undefined,
        velocity: options.velocity ?? (velocity ? Number(velocity) : undefined),
        qualityRating: outcome === "Ball" ? 2 : outcome === "Whiff" || outcome === "Called Strike" ? 5 : 4,
        missedIntendedLocation: resolvedLocation && resolvedTarget ? distanceBetween(resolvedLocation, resolvedTarget) > 0.18 : undefined,
        intendedTarget: resolvedTarget,
        location: resolvedLocation,
        countBefore,
        countAfter,
        createdAt,
        createdByProfileId: profileId,
        entrySource: "COACH",
        verificationStatus: "COACH_RECORDED",
        idempotencyKey: eventId,
        sessionSequence: nextSessionSequence(next.data.pitchEvents, session.id),
      };
      return touchRecentPlayers({ ...next.data, pitchEvents: [event, ...next.data.pitchEvents] }, practicePlayer.id);
    });
  }

  function updatePitchEvent(eventId: ID, update: {
    pitchType: PitchType;
    outcome: PitchOutcome;
    velocity?: number;
    location?: ZonePoint;
    intendedTarget?: ZonePoint;
    battedBall?: BattedBallType;
  }) {
    if (!practice) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const updatedAt = new Date().toISOString();
      let updatedSessionId: ID | undefined;
      const pitchEvents = current.pitchEvents.map((event) => {
        if (event.id !== eventId || event.practiceId !== practice.id) return event;
        updatedSessionId = event.sessionId;
        const isBip = update.outcome === "Ball in play";
        const isSwing = ["Swing", "Whiff", "Foul", "Ball in play"].includes(update.outcome);
        const isStrike = update.outcome !== "Ball" && update.outcome !== "HBP";
        const isZone = isPitchLocationInZone(update.location);
        return {
          ...event,
          pitchType: update.pitchType,
          outcome: update.outcome,
          isStrike,
          isSwing,
          isZone,
          isChase: update.location ? isSwing && !isZone : undefined,
          isWhiff: update.outcome === "Whiff",
          isCalledStrike: update.outcome === "Called Strike",
          isBallInPlay: isBip,
          battedBall: isBip ? update.battedBall : undefined,
          contactQuality: isBip ? (update.battedBall === "Line drive" ? "Hard contact" as const : "Medium contact" as const) : undefined,
          velocity: update.velocity,
          qualityRating: update.outcome === "Ball" ? 2 : update.outcome === "Whiff" || update.outcome === "Called Strike" ? 5 : 4,
          missedIntendedLocation: update.location && update.intendedTarget ? distanceBetween(update.location, update.intendedTarget) > 0.18 : undefined,
          intendedTarget: update.intendedTarget,
          location: update.location,
          countAfter: nextCount(event.countBefore ?? { balls: 0, strikes: 0 }, update.outcome),
          updatedByProfileId: profileId,
        };
      });
      if (!updatedSessionId) return current;
      return {
        ...current,
        pitchEvents,
        pitchingSessions: current.pitchingSessions.map((session) =>
          session.id === updatedSessionId ? { ...session, updatedAt, contributorProfileIds: withContributorProfile(session.contributorProfileIds, profileId) } : session,
        ),
        practiceSessionContributors: touchSessionContributor(current.practiceSessionContributors ?? [], { sessionId: updatedSessionId, profileId, at: updatedAt }),
      };
    });
  }

  function logLiveBpPitch(outcome: PitchOutcome, battedBall?: BattedBallType) {
    if (!practice || !data) return;
    const pitcher = data.players.find((player) => player.id === liveBpPitcherId);
    const hitter = data.players.find((player) => player.id === liveBpHitterId);
    if (!hitter || (liveBpThrowerSource === "PLAYER" && !pitcher)) return;
    const exitVelocityMph = parsePendingExitVelocity();
    if (exitVelocityMph === null) return;

    const countBefore = liveBpCount;
    const countAfter = nextCount(countBefore, outcome);
    const liveDisplayCountAfter = nextLiveBpDisplayCount(countBefore, outcome);
    const isBip = outcome === "Ball in play";
    const isSwing = ["Swing", "Whiff", "Foul", "Ball in play"].includes(outcome);
    const isStrike = outcome !== "Ball" && outcome !== "HBP";
    const isZone = pitchLocation ? pitchLocation.x >= 0.22 && pitchLocation.x <= 0.78 && pitchLocation.y >= 0.18 && pitchLocation.y <= 0.82 : false;
    const captureSpray = trackSprayChart && isBip;

    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      if (liveBpThrowerSource !== "PLAYER") {
        const hittingNext = ensureHittingSession(current, practice, hitter.id, "Live BP", profileId, liveBpThrowerSource);
        const hittingSession = hittingNext.session;
        const eventNumber = hittingNext.data.hittingEvents.filter((event) => event.sessionId === hittingSession.id).length + 1;
        const createdAt = new Date().toISOString();
        const hittingEventId = createId("he");
        const hittingEvent: HittingEvent = {
          id: hittingEventId,
          practiceId: practice.id,
          sessionId: hittingSession.id,
          hitterId: hitter.id,
          eventNumber,
          action: outcome === "Ball" || outcome === "Called Strike" ? "Took pitch" : outcome === "Whiff" ? "Miss" : outcome === "Foul" ? "Foul" : "Ball in play",
          contactResult: isBip ? battedBall : undefined,
          contactQuality: isBip ? (battedBall === "Line drive" ? "Hard" : "Solid") : undefined,
          direction: captureSpray ? hitDirection : undefined,
          fieldLocation: captureSpray ? fieldLocation : undefined,
          pitchLocation,
          pitchType: selectedPitchType,
          velocity: velocity ? Number(velocity) : undefined,
          exitVelocityMph: outcome === "Ball" || outcome === "Called Strike" ? undefined : exitVelocityMph,
          isLiveBp: true,
          createdAt,
          createdByProfileId: profileId,
          entrySource: "COACH",
          verificationStatus: "COACH_RECORDED",
          idempotencyKey: hittingEventId,
          sessionSequence: nextSessionSequence(hittingNext.data.hittingEvents, hittingSession.id),
        };
        return touchRecentPlayers({ ...hittingNext.data, hittingEvents: [hittingEvent, ...hittingNext.data.hittingEvents] }, hitter.id);
      }

      if (!pitcher) return current;
      const pitchingNext = ensurePitchingSession(current, practice, pitcher.id, "Live BP", profileId, hitter.id, liveBpThrowerSource);
      const pitchingSession = pitchingNext.session;
      const hittingNext = ensureHittingSession(pitchingNext.data, practice, hitter.id, "Live BP", profileId, liveBpThrowerSource);
      const hittingSession = hittingNext.session;
      const pitchNumber = hittingNext.data.pitchEvents.filter((event) => event.sessionId === pitchingSession.id).length + 1;
      const eventNumber = hittingNext.data.hittingEvents.filter((event) => event.sessionId === hittingSession.id).length + 1;
      const createdAt = new Date().toISOString();
      const pitchEventId = createId("pe");
      const hittingEventId = createId("he");
      const pitchEvent: PitchEvent = {
        id: pitchEventId,
        practiceId: practice.id,
        sessionId: pitchingSession.id,
        pitcherId: pitcher.id,
        hitterId: hitter.id,
        pitchNumber,
        pitchType: selectedPitchType,
        outcome,
        isStrike,
        isSwing,
        isZone,
        isChase: pitchLocation ? isSwing && !isZone : undefined,
        isWhiff: outcome === "Whiff",
        isCalledStrike: outcome === "Called Strike",
        isBallInPlay: isBip,
        battedBall: isBip ? battedBall : undefined,
        contactQuality: isBip ? (battedBall === "Line drive" ? "Hard contact" : "Medium contact") : undefined,
        velocity: velocity ? Number(velocity) : undefined,
        intendedTarget: targetLocation,
        location: pitchLocation,
        countBefore,
        countAfter,
        createdAt,
        createdByProfileId: profileId,
        entrySource: "COACH",
        verificationStatus: "COACH_RECORDED",
        idempotencyKey: pitchEventId,
        sessionSequence: nextSessionSequence(hittingNext.data.pitchEvents, pitchingSession.id),
      };
      const hittingEvent: HittingEvent = {
        id: hittingEventId,
        practiceId: practice.id,
        sessionId: hittingSession.id,
        hitterId: hitter.id,
        pitcherId: pitcher.id,
        eventNumber,
        action: outcome === "Ball" || outcome === "Called Strike" ? "Took pitch" : outcome === "Whiff" ? "Miss" : outcome === "Foul" ? "Foul" : "Ball in play",
        contactResult: isBip ? battedBall : undefined,
        contactQuality: isBip ? (battedBall === "Line drive" ? "Hard" : "Solid") : undefined,
        direction: captureSpray ? hitDirection : undefined,
        fieldLocation: captureSpray ? fieldLocation : undefined,
        pitchLocation,
        pitchType: selectedPitchType,
        velocity: velocity ? Number(velocity) : undefined,
        exitVelocityMph: outcome === "Ball" || outcome === "Called Strike" ? undefined : exitVelocityMph,
        isLiveBp: true,
        createdAt,
        createdByProfileId: profileId,
        entrySource: "COACH",
        verificationStatus: "COACH_RECORDED",
        idempotencyKey: hittingEventId,
        sessionSequence: nextSessionSequence(hittingNext.data.hittingEvents, hittingSession.id),
      };
      return touchRecentPlayers(
        touchRecentPlayers(
          { ...hittingNext.data, pitchEvents: [pitchEvent, ...hittingNext.data.pitchEvents], hittingEvents: [hittingEvent, ...hittingNext.data.hittingEvents] },
          pitcher.id,
        ),
        hitter.id,
      );
    });

    setLiveBpCount(liveDisplayCountAfter);
    clearPendingHittingContext();
  }

  function completeLiveBpPa(label: LiveBpOutcomeLabel) {
    if (!practice || !data) return;
    const pitcher = data.players.find((player) => player.id === liveBpPitcherId);
    const hitter = data.players.find((player) => player.id === liveBpHitterId);
    if (!hitter || (liveBpThrowerSource === "PLAYER" && !pitcher)) return;

    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      if (liveBpThrowerSource !== "PLAYER") {
        const hittingNext = ensureHittingSession(current, practice, hitter.id, "Live BP", profileId, liveBpThrowerSource);
        return touchRecentPlayers(hittingNext.data, hitter.id);
      }
      if (!pitcher) return current;
      const pitchingNext = ensurePitchingSession(current, practice, pitcher.id, "Live BP", profileId, hitter.id, liveBpThrowerSource);
      const hittingNext = ensureHittingSession(pitchingNext.data, practice, hitter.id, "Live BP", profileId, liveBpThrowerSource);
      const plateAppearance: PlateAppearance = {
        id: createId("pa"),
        practiceId: practice.id,
        pitchingSessionId: pitchingNext.session.id,
        hittingSessionId: hittingNext.session.id,
        pitcherId: pitcher.id,
        hitterId: hitter.id,
        startedAt: new Date().toISOString(),
        endedAt: new Date().toISOString(),
        outcome: mapLiveBpOutcome(label),
        balls: liveBpCount.balls,
        strikes: liveBpCount.strikes,
      };
      return touchRecentPlayers(
        touchRecentPlayers({ ...hittingNext.data, plateAppearances: [plateAppearance, ...hittingNext.data.plateAppearances] }, pitcher.id),
        hitter.id,
      );
    });
    setLiveBpCount({ balls: 0, strikes: 0 });
    setLiveBpPaNumber((value) => value + 1);
    advanceLiveBpHitter();
  }

  function advanceLiveBpHitter() {
    if (!data) return;
    const hitters = availablePracticePlayers(data, practice).filter((player) => player.isHitter && player.id !== liveBpPitcherId);
    if (!hitters.length) return;
    const currentIndex = hitters.findIndex((player) => player.id === liveBpHitterId);
    const next = hitters[(currentIndex + 1) % hitters.length] ?? hitters[0];
    setLiveBpHitterId(next.id);
  }

  function logDefense(draft: DefenseLogDraft) {
    if (!practice || !practicePlayer) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const next = ensureDefenseSession(current, practice, practicePlayer.id, defenseStationForDrill(draft.drillContext), profileId, {
        drillContext: draft.drillContext,
        positionWorked: draft.positionWorked,
      });
      const session = next.session;
      const eventNumber = next.data.defenseEvents.filter((event) => event.sessionId === session.id).length + 1;
      const eventId = createId("de");
      const createdAt = new Date().toISOString();
      const event: DefenseEvent = {
        id: eventId,
        practiceId: practice.id,
        sessionId: session.id,
        playerId: practicePlayer.id,
        station: session.station,
        eventNumber,
        outcome: draft.result,
        positionWorked: draft.positionWorked,
        drillContext: draft.drillContext,
        repType: draft.repType,
        repSubtype: draft.repSubtype,
        result: draft.result,
        throwResult: draft.throwResult,
        difficulty: draft.difficulty,
        location: draft.location,
        deviceSource: "manual",
        throwQuality: throwQualityForDefenseDraft(draft),
        footwork: draft.result === "Error" ? "Needs work" : draft.result === "Great Play" ? "Plus" : "Solid",
        decision: draft.result === "Great Play" ? "Advanced" : "Correct",
        range: defenseRangeForDraft(draft),
        errorType: draft.result === "Error" ? defenseErrorTypeForDraft(draft) : undefined,
        coachNote: draft.coachNote,
        createdAt,
        createdByProfileId: profileId,
        entrySource: "COACH",
        verificationStatus: "COACH_RECORDED",
        idempotencyKey: eventId,
        sessionSequence: nextSessionSequence(next.data.defenseEvents, session.id),
      };
      return touchRecentPlayers({ ...next.data, defenseEvents: [event, ...next.data.defenseEvents] }, practicePlayer.id);
    });
  }

  function updateDefenseEvent(eventId: ID, draft: DefenseLogDraft) {
    if (!practice || !practicePlayer) return;
    commit((current) => {
      const profileId = current.teamContext?.profile?.id;
      const next = ensureDefenseSession(current, practice, practicePlayer.id, defenseStationForDrill(draft.drillContext), profileId, {
        drillContext: draft.drillContext,
        positionWorked: draft.positionWorked,
      });
      return touchRecentPlayers({
        ...next.data,
        defenseEvents: next.data.defenseEvents.map((event) => event.id === eventId ? {
          ...event,
          sessionId: next.session.id,
          station: next.session.station,
          positionWorked: draft.positionWorked,
          drillContext: draft.drillContext,
          repType: draft.repType,
          repSubtype: draft.repSubtype,
          result: draft.result,
          outcome: draft.result,
          throwResult: draft.throwResult,
          difficulty: draft.difficulty,
          location: draft.location,
          deviceSource: "manual",
          throwQuality: throwQualityForDefenseDraft(draft),
          footwork: draft.result === "Error" ? "Needs work" : draft.result === "Great Play" ? "Plus" : "Solid",
          decision: draft.result === "Great Play" ? "Advanced" : "Correct",
          range: defenseRangeForDraft(draft),
          errorType: draft.result === "Error" ? defenseErrorTypeForDraft(draft) : undefined,
          coachNote: draft.coachNote,
        } : event),
      }, practicePlayer.id);
    });
  }

  function undoPracticeEvent() {
    if (!practice || !practicePlayer) return;
    commit((current) => {
      if (practiceMode === "Hitting") {
        const index = current.hittingEvents.findIndex((event) => event.practiceId === practice.id && event.hitterId === practicePlayer.id);
        if (index < 0) return current;
        return { ...current, hittingEvents: current.hittingEvents.filter((_, eventIndex) => eventIndex !== index) };
      }
      if (practiceMode === "Pitching") {
        const index = current.pitchEvents.findIndex((event) => event.practiceId === practice.id && event.pitcherId === practicePlayer.id);
        if (index < 0) return current;
        return { ...current, pitchEvents: current.pitchEvents.filter((_, eventIndex) => eventIndex !== index) };
      }
      if (practiceMode === "Live BP") {
        const pitchIndex = current.pitchEvents.findIndex((event) => event.practiceId === practice.id && event.pitcherId === liveBpPitcherId && event.hitterId === liveBpHitterId);
        const hitIndex = current.hittingEvents.findIndex((event) => event.practiceId === practice.id && event.hitterId === liveBpHitterId && event.pitcherId === liveBpPitcherId);
        return {
          ...current,
          pitchEvents: pitchIndex >= 0 ? current.pitchEvents.filter((_, eventIndex) => eventIndex !== pitchIndex) : current.pitchEvents,
          hittingEvents: hitIndex >= 0 ? current.hittingEvents.filter((_, eventIndex) => eventIndex !== hitIndex) : current.hittingEvents,
        };
      }
      const index = current.defenseEvents.findIndex((event) => event.practiceId === practice.id && event.playerId === practicePlayer.id);
      if (index < 0) return current;
      return { ...current, defenseEvents: current.defenseEvents.filter((_, eventIndex) => eventIndex !== index) };
    });
  }

  function openSessionSummary() {
    if (!data || !practice || !practicePlayer) return;
    let summaryType: "Hitting" | "Pitching" | "Defense" = "Hitting";
    const session =
      practiceMode === "Hitting"
        ? data.hittingSessions.find((item) => item.practiceId === practice.id && item.hitterId === practicePlayer.id && item.type === hittingStation && isPracticeSessionReusable(item))
        : practiceMode === "Pitching"
          ? data.pitchingSessions.find((item) => item.practiceId === practice.id && item.pitcherId === practicePlayer.id && item.type === pitchingStation && isPracticeSessionReusable(item))
          : practiceMode === "Live BP"
            ? data.pitchingSessions.find((item) => item.practiceId === practice.id && item.pitcherId === liveBpPitcherId && item.type === "Live BP" && isPracticeSessionReusable(item))
            : data.defenseSessions.find((item) => item.practiceId === practice.id && item.playerId === practicePlayer.id && item.station === defenseStation && isPracticeSessionReusable(item));
    if (!session) return;
    if (practiceMode === "Pitching" || practiceMode === "Live BP") summaryType = "Pitching";
    if (practiceMode === "Defense") summaryType = "Defense";
    setSummaryNote(session.summaryNote ?? "");
    setSessionSummary({ type: summaryType, sessionId: session.id });
  }

  function openExistingSessionSummary(type: "Hitting" | "Pitching" | "Defense", sessionId: ID) {
    if (!data) return;
    const session =
      type === "Hitting"
        ? data.hittingSessions.find((item) => item.id === sessionId)
        : type === "Pitching"
          ? data.pitchingSessions.find((item) => item.id === sessionId)
          : data.defenseSessions.find((item) => item.id === sessionId);
    setSummaryNote(session?.summaryNote ?? "");
    setSessionSummary({ type, sessionId });
  }

  function saveSessionSummary() {
    if (!sessionSummary) return;
    commit((current) => {
      const now = new Date().toISOString();
      if (sessionSummary.type === "Hitting") {
        return {
          ...current,
          hittingSessions: current.hittingSessions.map((session) =>
            session.id === sessionSummary.sessionId ? { ...session, updatedAt: now, summaryNote, sessionGrade: gradeSession(summaryNote) } : session,
          ),
        };
      }
      if (sessionSummary.type === "Pitching") {
        return {
          ...current,
          pitchingSessions: current.pitchingSessions.map((session) =>
            session.id === sessionSummary.sessionId ? { ...session, updatedAt: now, summaryNote, sessionGrade: gradeSession(summaryNote) } : session,
          ),
        };
      }
      return {
        ...current,
        defenseSessions: current.defenseSessions.map((session) =>
          session.id === sessionSummary.sessionId ? { ...session, updatedAt: now, summaryNote } : session,
        ),
      };
    });
    setSessionSummary(null);
  }

  function endPractice() {
    if (!practice) return;
    setPracticeSummaryOpen(true);
  }

  function savePracticeSummary() {
    if (!practice) return;
    const endedAt = new Date().toISOString();
    commit((current) => ({
      ...current,
      practices: current.practices.map((item) =>
        item.id === practice.id ? { ...item, endedAt, updatedAt: endedAt } : item,
      ),
      settings: { ...current.settings, activePracticeId: undefined },
    }));
    setPracticeTrackingOpen(false);
    setPracticeSummaryOpen(false);
    writePracticeReviewRoute(practice.id, "Summary", { replace: true });
  }

  function createPracticeRecord(practiceDraft: Practice, attendanceDraft: PracticeAttendance[], options: { openPractice?: boolean } = {}) {
    if (options.openPractice && practice && !practice.endedAt) {
      openCurrentPractice(practice);
      return;
    }
    commit((current) => {
      const existingOpenPractice = activePractice(current);
      if (options.openPractice && existingOpenPractice && !existingOpenPractice.endedAt) return current;
      return {
        ...current,
        practices: [practiceDraft, ...current.practices],
        attendance: [...attendanceDraft, ...current.attendance],
        settings: { ...current.settings, activePracticeId: options.openPractice ? practiceDraft.id : current.settings.activePracticeId },
      };
    });
    if (options.openPractice) {
      if (practiceDraft.playerIds[0]) {
        setPracticePlayerId(practiceDraft.playerIds[0]);
        setSelectedPlayerId(practiceDraft.playerIds[0]);
      }
      writePracticeHubRoute("Overview");
    }
  }

  function createGameRecord(game: Game, options: { openGame?: boolean } = {}) {
    commit((current) => gameRepository.upsert(current, game));
    setSelectedGameId(game.id);
    if (options.openGame) navigateToView("games");
  }

  function createScheduleEvent(event: ScheduleEvent) {
    commit((current) => ({ ...current, scheduleEvents: [event, ...(current.scheduleEvents ?? [])] }));
  }

  function updateScheduleEvent(event: ScheduleEvent) {
    commit((current) => ({
      ...current,
      scheduleEvents: (current.scheduleEvents ?? []).map((item) => (item.id === event.id ? event : item)),
    }));
  }

  function addWorkoutEntry(draft?: WeightRoomSetDraft) {
    if (!data) return;
    const playerId = draft?.playerId ?? selectedWeightPlayerId;
    const player = data.players.find((item) => item.id === playerId);
    if (!player) return;
    const date = draft?.date ?? new Date().toISOString().slice(0, 10);
    const weekOf = weekStart(date);
    const existingSession = data.workoutSessions.find((item) => item.playerId === player.id && item.date === date);
    const exercise = draft?.exercise ?? weightForm.exercise;
    const weight = draft?.weight ?? (Number(weightForm.weight) || undefined);
    const reps = draft?.reps ?? (Number(weightForm.reps) || undefined);
    const rpe = draft?.rpe ?? (Number(weightForm.effort) || undefined);
    const existingSets = data.workoutEntries.filter((entry) => entry.sessionId === existingSession?.id && entry.playerId === player.id && entry.exercise === exercise);
    const setNumber = draft?.setNumber ?? existingSets.length + 1;
    const session: WorkoutSession = {
      id: existingSession?.id ?? createId("ws"),
      playerId: player.id,
      date,
      weekOf,
      day: weekdayName(date),
      completed: true,
      effortScore: rpe || existingSession?.effortScore || 8,
      bodyWeight: player.weight,
      createdAt: existingSession?.createdAt ?? new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    const entry: WorkoutEntry = {
      id: createId("we"),
      sessionId: session.id,
      playerId: player.id,
      exercise,
      kind: draft?.kind ?? workoutExerciseKind(exercise),
      setNumber,
      weight,
      reps,
      sets: draft ? 1 : Number(weightForm.sets) || undefined,
      value: draft?.value,
      unit: draft?.unit,
      rpe,
      status: draft?.status ?? "Completed",
      createdByProfileId: data.teamContext?.profile?.id,
      entrySource: "COACH",
      priorValue: latestExerciseValue(data, player.id, exercise),
      createdAt: new Date().toISOString(),
    };
    commit((current) => {
      const withoutDuplicateSet = draft?.setNumber
        ? {
            ...current,
            workoutEntries: current.workoutEntries.filter((item) => !(item.sessionId === session.id && item.playerId === player.id && item.exercise === exercise && (item.setNumber ?? 1) === setNumber)),
          }
        : current;
      return workoutRepository.logEntry(withoutDuplicateSet, session, entry);
    });
  }

  function logWeightRoomWeighIns(rows: Array<{ playerId: ID; weight?: number }>, date: string) {
    const usableRows = rows.filter((row) => typeof row.weight === "number" && row.weight > 0);
    if (!usableRows.length) return;
    commit((current) => {
      let next = current;
      usableRows.forEach((row) => {
        const existingSession = next.workoutSessions.find((item) => item.playerId === row.playerId && item.date === date);
        const session: WorkoutSession = {
          id: existingSession?.id ?? createId("ws"),
          playerId: row.playerId,
          date,
          weekOf: weekStart(date),
          day: weekdayName(date),
          completed: existingSession?.completed ?? false,
          effortScore: existingSession?.effortScore ?? 0,
          bodyWeight: row.weight,
          createdAt: existingSession?.createdAt ?? new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };
        next = workoutRepository.upsertSession(next, session);
      });
      return next;
    });
  }

  function startWeightRoomWorkout(input: { title: string; date: string; location?: string; eventId?: ID }) {
    if (weightRoomWorkoutStatus === "In Progress" || weightRoomWorkoutStatus === "Paused") {
      setWeightRoomTab("WorkoutSession");
      return;
    }
    const now = new Date().toISOString();
    const startAt = `${input.date}T18:00:00.000Z`;
    const activeWorkout = (data?.weightRoomWorkouts ?? []).find((workout) => workout.status === "ACTIVE" || workout.status === "PAUSED")
      ?? (data?.weightRoomWorkouts ?? []).find((workout) =>
        workout.title === input.title
        && workout.date === input.date
        && workout.status !== "COMPLETED"
        && workout.status !== "CANCELLED"
      );
    const existingLiftEvent = data?.scheduleEvents.find((event) =>
      event.eventType === "Lift"
      && event.title === input.title
      && dateKeyFromIso(event.startAt) === input.date
      && event.status !== "Cancelled"
    );
    const newEventId = activeWorkout?.scheduleEventId ?? input.eventId ?? existingLiftEvent?.id ?? createId("se");
    const activeWorkoutId = activeWorkout?.id ?? createId("wrw");
    setWeightRoomWorkoutTitle(input.title);
    setWeightRoomWorkoutDate(input.date);
    setWeightRoomWorkoutStatus(activeWorkout?.status === "PAUSED" ? "Paused" : "In Progress");
    setWeightRoomActiveWorkoutId(activeWorkoutId);
    setWeightRoomActiveEventId(newEventId);
    commit((current) => {
      const workout: PersistedWeightRoomWorkout = {
        id: activeWorkoutId,
        organizationId: current.teamContext?.currentTeam?.organizationId,
        teamId: current.teamContext?.currentTeam?.teamId,
        seasonId: current.teamContext?.currentTeam?.seasonId,
        scheduleEventId: newEventId,
        title: input.title,
        date: input.date,
        status: activeWorkout?.status === "PAUSED" ? "PAUSED" : "ACTIVE",
        startedAt: activeWorkout?.startedAt ?? now,
        pausedAt: activeWorkout?.status === "PAUSED" ? activeWorkout.pausedAt : undefined,
        createdBy: current.teamContext?.profile?.id,
        createdAt: activeWorkout?.createdAt ?? now,
        updatedAt: now,
      };
      return {
        ...current,
        weightRoomWorkouts: upsertById(current.weightRoomWorkouts ?? [], workout),
      };
    });
    if (input.eventId || existingLiftEvent) {
      updateScheduleEventForWeightRoom(newEventId, { status: "Scheduled" });
      return;
    }
    createScheduleEvent({
      id: newEventId,
      organizationId: data?.teamContext?.currentTeam?.organizationId,
      teamId: data?.teamContext?.currentTeam?.teamId,
      seasonId: data?.teamContext?.currentTeam?.seasonId,
      teamIds: data?.teamContext?.currentTeam?.teamId ? [data.teamContext.currentTeam.teamId] : [],
      eventType: "Lift",
      title: input.title,
      startAt,
      location: input.location,
      visibility: "TEAM_ONLY",
      status: "Scheduled",
      createdBy: data?.teamContext?.profile?.id,
      createdAt: now,
      updatedAt: now,
    });
  }

  function completeWeightRoomWorkout() {
    setWeightRoomWorkoutStatus("Completed");
    if (weightRoomActiveEventId) updateScheduleEventForWeightRoom(weightRoomActiveEventId, { status: "Completed" });
    updateActiveWeightRoomWorkoutStatus("COMPLETED");
  }

  function openCompletedWeightRoomWorkout(workout: PersistedWeightRoomWorkout) {
    setWeightRoomWorkoutTitle(workout.title);
    setWeightRoomWorkoutDate(workout.date);
    setWeightRoomWorkoutStatus("Completed");
    setWeightRoomActiveWorkoutId(workout.id);
    setWeightRoomActiveEventId(workout.scheduleEventId);
    setWeightRoomTab("WorkoutSession");
  }

  function pauseWeightRoomWorkout() {
    setWeightRoomWorkoutStatus("Paused");
    if (weightRoomActiveEventId) updateScheduleEventForWeightRoom(weightRoomActiveEventId, { status: "Scheduled" });
    updateActiveWeightRoomWorkoutStatus("PAUSED");
  }

  function resumeWeightRoomWorkout() {
    setWeightRoomWorkoutStatus("In Progress");
    setWeightRoomTab("WorkoutSession");
    updateActiveWeightRoomWorkoutStatus("ACTIVE");
  }

  function updateActiveWeightRoomWorkoutStatus(status: PersistedWeightRoomWorkout["status"]) {
    if (!weightRoomActiveWorkoutId) return;
    const now = new Date().toISOString();
    commit((current) => ({
      ...current,
      weightRoomWorkouts: (current.weightRoomWorkouts ?? []).map((workout) =>
        workout.id === weightRoomActiveWorkoutId
          ? {
              ...workout,
              status,
              pausedAt: status === "PAUSED" ? now : workout.pausedAt,
              endedAt: status === "COMPLETED" ? now : workout.endedAt,
              updatedAt: now,
            }
          : workout,
      ),
    }));
  }

  function saveWeightRoomSetup(payload: WeightRoomSetupPayload) {
    commit((current) => applyWeightRoomSetupToData(current, payload));
  }

  function saveWeightRoomExerciseDefinition(exercise: WeightRoomExercise) {
    commit((current) => {
      const now = new Date().toISOString();
      return {
        ...current,
        weightRoomExercises: mergePersistedExerciseDefinitions(current.weightRoomExercises ?? [], [exercise], current.teamContext?.currentTeam?.organizationId, now),
      };
    });
  }

  function saveWeightRoomExercisePreset(preset: WeightRoomExercisePreset) {
    commit((current) => {
      const now = new Date().toISOString();
      const team = current.teamContext?.currentTeam;
      const profileId = current.teamContext?.profile?.id;
      const existingPreset = (current.weightRoomExercisePresets ?? []).find((item) => item.id === preset.id);
      const presetRow: PersistedWeightRoomExercisePreset = {
        id: preset.id,
        organizationId: team?.organizationId,
        teamId: team?.teamId,
        name: preset.name,
        archivedAt: preset.archived ? now : existingPreset?.archivedAt,
        createdBy: existingPreset?.createdBy ?? profileId,
        createdAt: existingPreset?.createdAt ?? now,
        updatedAt: now,
      };
      const existingPresetItemByExercise = new Map(
        (current.weightRoomExercisePresetItems ?? [])
          .filter((item) => item.presetId === preset.id)
          .map((item) => [item.exerciseName.toLowerCase(), item]),
      );
      const items: PersistedWeightRoomExercisePresetItem[] = preset.stations.map((station, index) => {
        const existingItem = existingPresetItemByExercise.get(station.name.toLowerCase());
        return {
          id: existingItem?.id ?? createId("wepi"),
          presetId: preset.id,
          exerciseName: station.name,
          displayOrder: index + 1,
          targetSets: station.targetSets,
          targetReps: station.targetReps,
          targetValue: station.targetValue,
          targetStyle: station.targetStyle,
          measurementType: station.measurementType,
          performanceDirection: station.performanceDirection,
          unit: station.unit,
          notes: station.notes,
          createdAt: existingItem?.createdAt ?? now,
          updatedAt: now,
        };
      });

      return {
        ...current,
        weightRoomExercises: mergePersistedExerciseDefinitions(current.weightRoomExercises ?? [], preset.stations, team?.organizationId, now),
        weightRoomExercisePresets: upsertById(current.weightRoomExercisePresets ?? [], presetRow),
        weightRoomExercisePresetItems: [
          ...(current.weightRoomExercisePresetItems ?? []).filter((item) => item.presetId !== preset.id),
          ...items,
        ],
      };
    });
  }

  function updateScheduleEventForWeightRoom(eventId: ID, patch: Partial<ScheduleEvent>) {
    if (!data) return;
    const event = data.scheduleEvents.find((item) => item.id === eventId);
    if (!event) return;
    updateScheduleEvent({ ...event, ...patch, updatedAt: new Date().toISOString() });
  }

  function logGamePitch(outcome: GamePitchOutcome, ballInPlayOutcome?: GameBallInPlayOutcome) {
    if (!currentGame) return;
    commit((current) => {
      const game = current.games.find((item) => item.id === currentGame.id);
      if (!game) return current;
      const nextGame = applyGameOutcome(game, outcome, ballInPlayOutcome);
      const event = {
        id: createId("ge"),
        gameId: game.id,
        inning: game.inning,
        half: game.half,
        pitcherId: game.currentPitcherId,
        batterId: game.currentBatterId,
        pitchType: selectedPitchType,
        pitchOutcome: outcome,
        ballInPlayOutcome,
        velocity: velocity ? Number(velocity) : undefined,
        location: pitchLocation,
        outsBefore: game.outs,
        outsAfter: nextGame.outs,
        metrolinaRunsBefore: game.metrolinaScore,
        metrolinaRunsAfter: nextGame.metrolinaScore,
        opponentRunsBefore: game.opponentScore,
        opponentRunsAfter: nextGame.opponentScore,
        situations: gameSituations(game, outcome, ballInPlayOutcome),
        createdAt: new Date().toISOString(),
      };
      return gameRepository.logEvent(current, event, nextGame);
    });
  }

  function adjustGame(field: "metrolinaScore" | "opponentScore" | "outs", delta: number) {
    if (!currentGame) return;
    commit((current) =>
      gameRepository.upsert(current, {
        ...currentGame,
        [field]: Math.max(0, Number(currentGame[field]) + delta),
        updatedAt: new Date().toISOString(),
      }),
    );
  }

