type ChoiceOption = {
  value: string;
  label: string;
  description?: string;
  icon?: React.ReactNode;
};
type ChoiceSelectMobilePresentation = "auto" | "popover" | "sheet";

function ChoiceSelect({
  label,
  value,
  options,
  onChange,
  className = "",
  disabled = false,
  showSelectedDescription = true,
  placeholder = "Select",
  open: controlledOpen,
  onOpenChange,
  mobilePresentation = "auto",
  "aria-label": ariaLabel,
}: {
  label?: string;
  value: string;
  options: ChoiceOption[];
  onChange: (value: string) => void;
  className?: string;
  disabled?: boolean;
  showSelectedDescription?: boolean;
  placeholder?: string;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  mobilePresentation?: ChoiceSelectMobilePresentation;
  "aria-label"?: string;
}) {
  const [internalOpen, setInternalOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState<{
    top: number;
    left: number;
    width: number;
    maxHeight: number;
    placement: "top" | "bottom" | "sheet";
  } | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const menuRef = useRef<HTMLDivElement | null>(null);
  const didInitialSelectedScrollRef = useRef(false);
  const selected = options.find((option) => option.value === value);
  const reactId = useId();
  const listboxId = `choice-select-${reactId.replace(/[^a-z0-9_-]/gi, "")}`;
  const open = controlledOpen ?? internalOpen;
  const { edges: menuEdges } = useScrollEdges(menuRef, `${open}-${menuPosition?.top ?? 0}-${menuPosition?.maxHeight ?? 0}-${options.length}-${value}`);
  const setSelectOpen = useCallback((nextOpen: boolean | ((current: boolean) => boolean)) => {
    const resolved = typeof nextOpen === "function" ? nextOpen(open) : nextOpen;
    if (controlledOpen === undefined) setInternalOpen(resolved);
    onOpenChange?.(resolved);
  }, [controlledOpen, onOpenChange, open]);

  const updateMenuPosition = useCallback(() => {
    if (!buttonRef.current || typeof window === "undefined") return;
    const rect = buttonRef.current.getBoundingClientRect();
    const viewportPadding = 12;
    const gap = 6;
    const viewport = window.visualViewport;
    const viewportTop = viewport?.offsetTop ?? 0;
    const viewportLeft = viewport?.offsetLeft ?? 0;
    const viewportHeight = viewport?.height ?? window.innerHeight;
    const viewportWidth = viewport?.width ?? window.innerWidth;
    const viewportBottom = viewportTop + viewportHeight;
    const viewportRight = viewportLeft + viewportWidth;
    const optionHeight = 44;
    const desiredHeight = Math.min(320, Math.max(96, options.length * optionHeight + 16));
    const availableBelow = Math.max(0, viewportBottom - rect.bottom - viewportPadding - gap);
    const availableAbove = Math.max(0, rect.top - viewportTop - viewportPadding - gap);
    const bestAvailable = Math.max(availableBelow, availableAbove);
    const shouldUseSheet = mobilePresentation === "sheet" || (
      mobilePresentation === "auto" && (viewportWidth <= 640 || (viewportWidth <= 900 && viewportHeight <= 540) || bestAvailable < 132)
    );
    if (shouldUseSheet) {
      const maxHeight = Math.min(320, Math.max(196, viewportHeight - viewportPadding * 2));
      setMenuPosition({
        top: viewportTop + Math.max(viewportPadding, viewportHeight - maxHeight - viewportPadding),
        left: viewportLeft + 8,
        width: viewportWidth - 16,
        maxHeight,
        placement: "sheet",
      });
      return;
    }

    const canFitBelow = availableBelow >= desiredHeight;
    const canFitAbove = availableAbove >= desiredHeight;
    const placement = canFitBelow || (!canFitAbove && availableBelow >= availableAbove) ? "bottom" : "top";
    const availableHeight = placement === "top" ? availableAbove : availableBelow;
    const maxHeight = Math.max(96, Math.min(320, availableHeight));
    const menuHeight = Math.min(desiredHeight, maxHeight);
    const widestOption = Math.min(320, Math.max(180, ...options.map((option) => (option.label.length + (option.description?.length ?? 0) * 0.45) * 7.5 + 42)));
    const width = Math.min(Math.max(rect.width, widestOption), viewportWidth - viewportPadding * 2);
    const left = Math.min(Math.max(rect.left, viewportLeft + viewportPadding), viewportRight - width - viewportPadding);
    const unclampedTop = placement === "top"
      ? rect.top - gap - menuHeight
      : rect.bottom + gap;
    const top = Math.min(
      Math.max(unclampedTop, viewportTop + viewportPadding),
      viewportBottom - menuHeight - viewportPadding,
    );
    setMenuPosition({ top, left, width, maxHeight, placement });
  }, [mobilePresentation, options]);

  const focusOption = useCallback((index?: number) => {
    const buttons = Array.from(menuRef.current?.querySelectorAll<HTMLButtonElement>('[role="option"]') ?? []);
    if (!buttons.length) return;
    const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
    const targetIndex = Math.max(0, Math.min(buttons.length - 1, index ?? selectedIndex));
    buttons[targetIndex]?.focus();
    buttons[targetIndex]?.scrollIntoView({ block: "nearest" });
  }, [options, value]);

  const closeMenu = useCallback((returnFocus = false) => {
    setSelectOpen(false);
    if (returnFocus) window.setTimeout(() => buttonRef.current?.focus(), 0);
  }, [setSelectOpen]);

  useEffect(() => {
    if (!open) didInitialSelectedScrollRef.current = false;
  }, [open]);

  const handleMenuKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeMenu(true);
      return;
    }
    const buttons = Array.from(menuRef.current?.querySelectorAll<HTMLButtonElement>('[role="option"]') ?? []);
    if (!buttons.length) return;
    const currentIndex = Math.max(0, buttons.findIndex((button) => button === document.activeElement));
    if (event.key === "ArrowDown") {
      event.preventDefault();
      focusOption(Math.min(buttons.length - 1, currentIndex + 1));
    }
    if (event.key === "ArrowUp") {
      event.preventDefault();
      focusOption(Math.max(0, currentIndex - 1));
    }
    if (event.key === "Home") {
      event.preventDefault();
      focusOption(0);
    }
    if (event.key === "End") {
      event.preventDefault();
      focusOption(buttons.length - 1);
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      const currentOption = options[currentIndex];
      if (!currentOption) return;
      onChange(currentOption.value);
      closeMenu(true);
    }
  };

  useEffect(() => {
    if (!open) return;

    updateMenuPosition();
    const animationFrame = window.requestAnimationFrame(updateMenuPosition);
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target instanceof Node ? event.target : null;
      if (
        target &&
        (rootRef.current?.contains(target) || menuRef.current?.contains(target))
      ) {
        return;
      }
      closeMenu();
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeMenu(true);
    };
    const handleFocusIn = (event: FocusEvent) => {
      const target = event.target instanceof Node ? event.target : null;
      if (
        target &&
        (rootRef.current?.contains(target) || menuRef.current?.contains(target))
      ) {
        return;
      }
      closeMenu();
    };
    window.addEventListener("resize", updateMenuPosition);
    window.addEventListener("orientationchange", updateMenuPosition);
    window.addEventListener("scroll", updateMenuPosition, true);
    window.visualViewport?.addEventListener("resize", updateMenuPosition);
    window.visualViewport?.addEventListener("scroll", updateMenuPosition);
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    document.addEventListener("focusin", handleFocusIn);
    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.removeEventListener("resize", updateMenuPosition);
      window.removeEventListener("orientationchange", updateMenuPosition);
      window.removeEventListener("scroll", updateMenuPosition, true);
      window.visualViewport?.removeEventListener("resize", updateMenuPosition);
      window.visualViewport?.removeEventListener("scroll", updateMenuPosition);
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("focusin", handleFocusIn);
    };
  }, [closeMenu, open, updateMenuPosition]);

  useEffect(() => {
    if (!open || !menuPosition || didInitialSelectedScrollRef.current) return;
    didInitialSelectedScrollRef.current = true;
    const animationFrame = window.requestAnimationFrame(() => {
      const selectedButton = menuRef.current?.querySelector<HTMLElement>('[aria-selected="true"]');
      selectedButton?.scrollIntoView({ block: "nearest" });
    });
    return () => window.cancelAnimationFrame(animationFrame);
  }, [menuPosition, open]);

  const menu = open && !disabled && menuPosition && typeof document !== "undefined"
    ? createPortal(
      <>
        {menuPosition.placement === "sheet" && <div className="choice-select__sheet-scrim" aria-hidden="true" />}
        <div
          ref={menuRef}
          id={listboxId}
          className={[
            "choice-select__menu",
            "choice-select__menu--portal",
            menuEdges.canScrollUp ? "has-scroll-up" : "",
            menuEdges.canScrollDown ? "has-scroll-down" : "",
            className,
          ].filter(Boolean).join(" ")}
          data-placement={menuPosition.placement}
          role="listbox"
          tabIndex={-1}
          aria-label={ariaLabel ?? label}
          onKeyDown={handleMenuKeyDown}
          style={{
            top: menuPosition.top,
            left: menuPosition.left,
            width: menuPosition.width,
            maxHeight: menuPosition.maxHeight,
          }}
        >
          <span className="choice-select__menu-edge choice-select__menu-edge--top" aria-hidden="true">
            <ChevronUp size={13} aria-hidden="true" />
          </span>
          {options.map((option) => (
            <button
              key={option.value}
              type="button"
              className={option.value === value ? "active" : ""}
              role="option"
              aria-selected={option.value === value}
              onClick={() => {
                onChange(option.value);
                closeMenu(true);
              }}
            >
              {option.icon && <span className="choice-select__icon">{option.icon}</span>}
              <span>
                {option.label}
                {option.description && <small>{option.description}</small>}
              </span>
            </button>
          ))}
          <span className="choice-select__menu-edge choice-select__menu-edge--bottom" aria-hidden="true">
            <ChevronDown size={13} aria-hidden="true" />
          </span>
        </div>
      </>,
      document.body,
    )
    : null;

  return (
    <div
      ref={rootRef}
      className={["choice-select", open ? "open" : "", className].filter(Boolean).join(" ")}
      data-label={ariaLabel ?? label}
      data-empty={!selected ? "true" : undefined}
    >
      {label && <span className="choice-select__label">{label}</span>}
      <button
        ref={buttonRef}
        type="button"
        className="choice-select__button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        aria-label={ariaLabel ?? label}
        disabled={disabled}
        onClick={() => {
          updateMenuPosition();
          setSelectOpen((current) => !current);
        }}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            updateMenuPosition();
            setSelectOpen(true);
            didInitialSelectedScrollRef.current = true;
            window.setTimeout(() => focusOption(event.key === "ArrowUp" ? options.length - 1 : undefined), 0);
          }
        }}
      >
        {selected?.icon && <span className="choice-select__icon">{selected.icon}</span>}
        <strong>
          {selected?.label ?? placeholder}
          {showSelectedDescription && selected?.description && <small>{selected.description}</small>}
        </strong>
        <ChevronDown size={14} aria-hidden="true" />
      </button>
      {menu}
    </div>
  );
}

function TeamSwitcher({
  context,
  onSwitch,
  compact = false,
}: {
  context?: TeamContext;
  onSwitch: (team: TeamOption) => void | Promise<void>;
  compact?: boolean;
}) {
  const teams = context?.availableTeams ?? [];
  const current = context?.currentTeam;
  if (!current) return null;

  const selectedValue = teamValue(current);
  const visibleTeams = displayWorkspaceTeams(teams);
  const switchTeams = visibleTeams.some((team) => teamValue(team) === selectedValue) ? visibleTeams : teams;

  return (
    <div className={`team-switcher ${compact ? "team-switcher--compact" : ""}`}>
      <OrganizationLogo name={current.organizationName} />
      <span>
        <small>{current.organizationName}</small>
        {switchTeams.length > 1 ? (
          <ChoiceSelect
            value={selectedValue}
            aria-label="Current team"
            className="team-switch-choice"
            options={switchTeams.map((team) => ({ value: teamValue(team), label: `${team.teamName} - ${team.seasonName ?? "Current season"}` }))}
            onChange={(value) => {
              const next = switchTeams.find((team) => teamValue(team) === value);
              if (next) void onSwitch(next);
            }}
          />
        ) : (
          <strong>{current.teamName}</strong>
        )}
      </span>
    </div>
  );
}

function TeamWorkspaceHeader({
  context,
  view,
  onSwitch,
  onClubhouseHome,
  hasOpenPractice,
  onStartPractice,
  onStartGame,
}: {
  context?: TeamContext;
  view: ViewKey;
  onSwitch: (team: TeamOption) => void | Promise<void>;
  onClubhouseHome: () => void;
  hasOpenPractice?: boolean;
  onStartPractice: () => void;
  onStartGame: () => void;
}) {
  const current = context?.currentTeam;
  if (!current) return null;
  const isTeamHome = view === "teamHome";
  if (!isTeamHome) {
    return (
      <section className="team-workspace-header team-workspace-header--compact">
        <OrganizationLogo name={current.organizationName} logoUrl={teamOrganizationLogo(current, context)} />
        <div className="team-workspace-header__identity">
          <span>{current.organizationName}</span>
          <TeamIdentitySwitcher context={context} current={current} onSwitch={onSwitch} onClubhouseHome={onClubhouseHome} compact />
          <small>{current.seasonName ?? "Current season"}</small>
        </div>
      </section>
    );
  }
  return (
    <section className="team-workspace-header team-workspace-header--home">
      <OrganizationLogo name={current.organizationName} logoUrl={teamOrganizationLogo(current, context)} />
      <div className="team-workspace-header__identity">
        <span>{current.organizationName}</span>
        <TeamIdentitySwitcher context={context} current={current} onSwitch={onSwitch} onClubhouseHome={onClubhouseHome} />
        <small>{current.seasonName ?? "Current season"}</small>
      </div>
      <div className="team-workspace-header__actions">
        <button type="button" className="primary-button" onClick={onStartPractice}>
          {hasOpenPractice ? <ChevronRight size={16} aria-hidden="true" /> : <Plus size={16} aria-hidden="true" />}
          {hasOpenPractice ? "Open Practice" : "Practice"}
        </button>
        <button type="button" className="secondary-button" onClick={onStartGame}>
          <Plus size={16} aria-hidden="true" />
          Game
        </button>
      </div>
    </section>
  );
}

function TeamIdentitySwitcher({
  context,
  current,
  onSwitch,
  onClubhouseHome,
  compact = false,
}: {
  context?: TeamContext;
  current: TeamOption;
  onSwitch: (team: TeamOption) => void | Promise<void>;
  onClubhouseHome: () => void;
  compact?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const organizations = organizationSummariesFromContext(context).filter((organization) => organization.teams.length > 0);
  const selectedValue = teamValue(current);

  return (
    <div
      className={`team-identity-switcher ${compact ? "team-identity-switcher--compact" : ""}`}
      onBlur={(event) => {
        const nextFocus = event.relatedTarget instanceof Node ? event.relatedTarget : null;
        if (!nextFocus || !event.currentTarget.contains(nextFocus)) setOpen(false);
      }}
    >
      <button type="button" className="team-identity-switcher__button" onClick={() => setOpen((value) => !value)} aria-haspopup="dialog" aria-expanded={open}>
        <strong>{current.teamName}</strong>
        <ChevronDown size={16} aria-hidden="true" />
      </button>
      {open && (
        <div className="team-identity-switcher__panel">
          {organizations.map((organization) => (
            <div className="team-switcher-group" key={organization.id}>
              <div className="team-switcher-group__heading">
                <OrganizationLogo name={organization.name} logoUrl={organization.logoUrl} />
                <strong>{organization.name}</strong>
              </div>
              {organization.teams.map((team) => (
                <button
                  key={teamValue(team)}
                  type="button"
                  className={teamValue(team) === selectedValue ? "active" : ""}
                  onClick={() => {
                    setOpen(false);
                    void onSwitch(team);
                  }}
                >
                  <span>
                    <strong>{team.teamName}</strong>
                    <small>{team.seasonName ?? "Current season"}</small>
                  </span>
                  {teamValue(team) === selectedValue ? <Check size={15} aria-hidden="true" /> : <ChevronRight size={15} aria-hidden="true" />}
                </button>
              ))}
            </div>
          ))}
          <button className="team-switcher-home-row" type="button" onClick={() => { setOpen(false); onClubhouseHome(); }}>
            <ChevronLeft size={15} aria-hidden="true" />
            Clubhouse Home
          </button>
        </div>
      )}
    </div>
  );
}

function ProfileMenu({
  context,
  open,
  onOpen,
  onView,
  onSignOut,
  variant = "icon",
}: {
  context?: TeamContext;
  open: boolean;
  onOpen: (open: boolean) => void;
  onView: (view: ViewKey) => void;
  onSignOut: () => void | Promise<void>;
  variant?: "icon" | "card";
}) {
  const profile = context?.profile;
  const profileName = profileDisplayName(context);
  const role = context?.currentTeam?.title ?? roleLabel(context?.currentTeam?.role) ?? profile?.role ?? "Coach";
  function handleProfileClick() {
    if (variant === "icon") {
      onOpen(false);
      onView("account");
      return;
    }
    onOpen(!open);
  }

  return (
    <div className={`profile-menu profile-menu--${variant}`}>
      <button className="profile-menu__button" type="button" onClick={handleProfileClick} aria-label={variant === "icon" ? "Open profile" : "Open profile menu"} aria-expanded={variant === "card" ? open : undefined}>
        <IdentityAvatar
          id={profile?.id ?? profile?.email}
          name={profileName}
          src={profile?.avatarUrl}
          size="sm"
          className="profile-menu__avatar"
        />
        {variant === "card" && (
          <span className="profile-menu__identity">
            <strong>{profileName}</strong>
            <small>{role}</small>
          </span>
        )}
      </button>
      {variant === "card" && open && (
        <div className="profile-menu__panel">
          <div>
            <strong>{profileName}</strong>
            <small>{profile?.email ?? "Coach account"}</small>
          </div>
          <button type="button" onClick={() => { onOpen(false); onView("account"); }}>
            <User size={15} aria-hidden="true" />
            My Profile
          </button>
          <button type="button" onClick={() => { onOpen(false); onView("teams"); }}>
            <Users size={15} aria-hidden="true" />
            Teams
          </button>
          <button type="button" onClick={() => { onOpen(false); onView("account"); }}>
            <Shield size={15} aria-hidden="true" />
            Settings
          </button>
          <button type="button" onClick={() => void onSignOut()}>
            <LogOut size={15} aria-hidden="true" />
            Sign Out
          </button>
        </div>
      )}
    </div>
  );
}

type MobileMoreMenuItem = {
  view: ViewKey;
  label: string;
  icon: AppIcon;
  dividerBefore?: boolean;
};

function MobileMoreMenu({
  inTeamContext,
  activeView,
  profile,
  style,
  onClose,
  onNavigate,
}: {
  inTeamContext: boolean;
  activeView: ViewKey;
  profile?: AppProfile;
  style?: React.CSSProperties;
  onClose: () => void;
  onNavigate: (view: ViewKey) => void;
}) {
  const items: MobileMoreMenuItem[] = inTeamContext
    ? [
        { view: "home", label: "Clubhouse Home", icon: Home },
        { view: "roster", label: "Roster", icon: Users },
        { view: "weights", label: "Weight Room", icon: Dumbbell },
        { view: "analytics", label: "Analytics", icon: BarChart3 },
        { view: "account", label: "My Profile", icon: User, dividerBefore: true },
      ]
    : [
        { view: "organizations", label: "Organizations", icon: Building2 },
        { view: "teams", label: "Teams", icon: Building2 },
        { view: "account", label: "My Profile", icon: User, dividerBefore: true },
      ];

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") onClose();
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  return (
    <>
      <button className="mobile-more-dismiss" type="button" aria-label="Close more menu" onClick={onClose} />
      <div className="mobile-more-menu" role="menu" aria-label="More navigation" style={style}>
        <span className="mobile-more-menu__handle" aria-hidden="true" />
        <div className="mobile-more-menu__title">More</div>
        <div className="mobile-more-menu__rows">
          {items.map(({ view: itemView, label, icon: Icon, dividerBefore }) => (
            <button
              key={`${itemView}-${label}`}
              type="button"
              role="menuitem"
              className={[
                "mobile-more-menu__row",
                activeView === itemView ? "active" : "",
                dividerBefore ? "with-divider" : "",
              ].filter(Boolean).join(" ")}
              onClick={() => onNavigate(itemView)}
            >
              {itemView === "account" ? (
                <IdentityAvatar
                  id={profile?.id}
                  name={preferredProfileDisplayName(profile) || "My Profile"}
                  src={profile?.avatarUrl}
                  size="xs"
                  className="mobile-more-menu__avatar"
                />
              ) : (
                <Icon size={18} aria-hidden="true" />
              )}
              <span>{label}</span>
              <ChevronRight size={15} aria-hidden="true" />
            </button>
          ))}
        </div>
      </div>
    </>
  );
}

