function SessionList({ data, player }: { data: AppData; player: Player }) {
  const sessions = [
    ...data.hittingSessions.filter((session) => session.hitterId === player.id).map((session) => ({ id: session.id, label: session.type, type: "Hitting", date: data.practices.find((practice) => practice.id === session.practiceId)?.date })),
    ...data.pitchingSessions.filter((session) => session.pitcherId === player.id).map((session) => ({ id: session.id, label: session.type, type: "Pitching", date: data.practices.find((practice) => practice.id === session.practiceId)?.date })),
    ...data.defenseSessions.filter((session) => session.playerId === player.id).map((session) => ({ id: session.id, label: session.station, type: "Defense", date: data.practices.find((practice) => practice.id === session.practiceId)?.date })),
  ].sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));

  return (
    <div className="entry-list">
      {sessions.slice(0, 8).map((session) => (
        <div key={session.id}><span>{session.type}</span><strong>{session.label}</strong><small>{session.date ? fullDate(session.date) : "Practice"}</small></div>
      ))}
    </div>
  );
}

function GamePlayerSummary({ data, player }: { data: AppData; player: Player }) {
  const battingEvents = data.gameEvents.filter((event) => event.batterId === player.id);
  const pitchingEvents = data.gameEvents.filter((event) => event.pitcherId === player.id);
  const hits = battingEvents.filter((event) => event.ballInPlayOutcome && ["Single", "Double", "Triple", "Home Run"].includes(event.ballInPlayOutcome)).length;
  const pa = Math.max(1, battingEvents.filter((event) => event.pitchOutcome === "In Play" || event.pitchOutcome === "Ball" || event.pitchOutcome === "Swinging Strike").length);
  return (
    <div className="mini-stat-grid">
      <StatTile label="PA" value={pa} />
      <StatTile label="Hits" value={hits} />
      <StatTile label="AVG" value={formatDecimal(hits / pa)} />
      <StatTile label="Pitches" value={pitchingEvents.length} accent />
    </div>
  );
}

interface AwardResult {
  player: Player;
  score: number;
  reasons: string[];
}

interface WeightLeaderResult {
  player: Player;
  score: number;
  reasons: string[];
  breakdown?: Array<{ label: string; value: number; max: number }>;
  qualified?: boolean;
  sessions?: number;
  completedSessions?: number;
  sets?: number;
  volume?: number;
  progressPct?: number;
  completionPct?: number;
  attendancePct?: number;
  hasComparableHistory?: boolean;
  relativePerformanceAvailable?: boolean;
  effortAvailable?: boolean;
  scoreVersion?: string;
}

function buildWeeklyMvp(data: AppData): AwardResult | undefined {
  const latestDate = data.practices.slice().sort((a, b) => b.date.localeCompare(a.date))[0]?.date ?? "2026-08-08";
  const start = new Date(`${latestDate}T12:00:00`);
  start.setDate(start.getDate() - 7);
  const recentPracticeIds = new Set(data.practices.filter((practice) => new Date(`${practice.date}T12:00:00`) >= start).map((practice) => practice.id));

  const awards = data.players.filter((player) => !player.archived).map((player) => {
    const recentHittingEvents = data.hittingEvents.filter((event) => event.hitterId === player.id && recentPracticeIds.has(event.practiceId));
    const hittingStats = calculateHittingStats(recentHittingEvents);
    const pitchingStats = calculatePitchingStats(data.pitchEvents.filter((event) => event.pitcherId === player.id && recentPracticeIds.has(event.practiceId)));
    const defenseEvents = data.defenseEvents.filter((event) => event.playerId === player.id && recentPracticeIds.has(event.practiceId));
    const gameEvents = data.gameEvents.filter((event) => event.batterId === player.id || event.pitcherId === player.id);
    const attendance = data.attendance.filter((item) => item.playerId === player.id && recentPracticeIds.has(item.practiceId)).length;
    const defenseScore = pct(defenseEvents.filter((event) => event.outcome !== "Error").length, defenseEvents.length);
    const liveAtBats = recentHittingEvents.filter((event) => event.isLiveBp && event.action !== "Took pitch").length;
    const score =
      hittingStats.hardHitPct * 0.22 +
      hittingStats.contactPct * 0.18 +
      hittingStats.barrelPct * 0.12 +
      pitchingStats.strikePct * 0.16 +
      pitchingStats.cswPct * 0.12 +
      defenseScore * 0.08 +
      Math.min(100, attendance * 22) * 0.07 +
      Math.min(100, gameEvents.length * 18) * 0.05;

    return {
      player,
      score,
      reasons: [
        liveAtBats ? `${formatPct(hittingStats.liveBpAvg * 100, 0)} Live BP AVG` : undefined,
        hittingStats.ballsInPlay ? `${Math.round(hittingStats.barrelPct)}% impact contact` : undefined,
        hittingStats.ballsInPlay ? `${Math.round(hittingStats.hardHitPct)}% hard contact` : undefined,
        pitchingStats.totalPitches ? `${Math.round(pitchingStats.strikePct)}% strike rate` : `${attendance} practices attended`,
      ].filter((reason): reason is string => Boolean(reason)),
    };
  });

  return awards.sort((a, b) => b.score - a.score)[0];
}

function buildWeightLeader(data: AppData): WeightLeaderResult | undefined {
  return buildScoredWeightRoomLeaderboard(
    data.players.filter((player) => !player.archived),
    data.workoutSessions,
    data.workoutEntries,
    "This Season",
  )[0];
}

function buildWeightMetrics(data: AppData, playerId: ID) {
  const player = data.players.find((item) => item.id === playerId);
  const entries = data.workoutEntries.filter((entry) => entry.playerId === playerId);
  const squat = latestExercise(entries, "Back Squat");
  const bench = latestExercise(entries, "Bench Press");
  const bodyWeight = latestBodyWeight(data, playerId) ?? player?.weight ?? 0;
  const previousWeight = previousBodyWeight(data, playerId, todayKey());
  const trend = entries.slice(0, 8).reverse().map((entry) => entry.weight ?? entry.value ?? 0).filter(Boolean);
  const score = buildWeightLeader({ ...data, players: player ? [player] : [] })?.score ?? 0;

  return {
    bodyWeight,
    bodyDelta: typeof previousWeight === "number" && bodyWeight ? `${bodyWeight - previousWeight > 0 ? "+" : ""}${formatNumber(bodyWeight - previousWeight, 1)} lb` : "baseline",
    squat: squat?.weight ? `${squat.weight}` : "--",
    squatDelta: squat?.priorValue && squat.weight ? `+${squat.weight - squat.priorValue} lb` : "baseline",
    bench: bench?.weight ? `${bench.weight}` : "--",
    benchDelta: bench?.priorValue && bench.weight ? `+${bench.weight - bench.priorValue} lb` : "baseline",
    score,
    trend,
  };
}

function latestExercise(entries: Array<{ exercise: string; weight?: number; priorValue?: number }>, exercise: string) {
  return entries.find((entry) => entry.exercise === exercise);
}

function workoutExerciseKind(exercise: string): ExerciseKind {
  const normalized = exercise.toLowerCase();
  if (/(sprint|dash|run|agility|shuttle)/.test(normalized)) return "Speed";
  if (/(jump|broad|vertical|hop)/.test(normalized)) return "Jump";
  if (/(plank|hold|mobility|test)/.test(normalized)) return "Test";
  if (/(squat|press|deadlift|clean|row|pull|curl|lunge|raise|bench|hinge|barbell|dumbbell|db)/.test(normalized)) return "Lift";
  return "Custom";
}

function buildWeightRoomExerciseLibrary(data: AppData): WeightRoomExercise[] {
  const byName = new Map<string, WeightRoomExercise>();
  for (const exercise of WEIGHT_ROOM_BASE_EXERCISES) {
    byName.set(exercise.name.toLowerCase(), exercise);
  }
  for (const exercise of data.weightRoomExercises ?? []) {
    if (exercise.archivedAt || !exercise.active) continue;
    byName.set(exercise.name.toLowerCase(), {
      name: exercise.name,
      category: (exercise.category as WeightRoomExerciseCategory | undefined) ?? weightRoomExerciseCategory(exercise.name, exercise.kind),
      measurementType: exercise.measurementType ?? weightRoomMeasurementType(exercise.name),
      kind: exercise.kind,
      unit: exercise.unit ?? weightRoomUnitForType(exercise.measurementType ?? weightRoomMeasurementType(exercise.name)),
      equipment: exercise.equipment,
      defaultTargetStyle: exercise.defaultTargetStyle,
      performanceDirection: exercise.performanceDirection,
      active: exercise.active,
    });
  }
  for (const entry of data.workoutEntries) {
    const key = entry.exercise.toLowerCase();
    if (!byName.has(key)) byName.set(key, makeWeightRoomExercise(entry.exercise));
  }
  for (const exerciseName of EXERCISES) {
    const key = exerciseName.toLowerCase();
    if (!byName.has(key)) byName.set(key, makeWeightRoomExercise(exerciseName));
  }
  return [...byName.values()].sort((left, right) => left.category.localeCompare(right.category) || left.name.localeCompare(right.name));
}

function makeWeightRoomExercise(name: string): WeightRoomExercise {
  const measurementType = weightRoomMeasurementType(name);
  const kind = workoutExerciseKind(name);
  const targetStyle = defaultTargetStyle(name, measurementType);
  return {
    name,
    category: weightRoomExerciseCategory(name, kind),
    measurementType,
    kind,
    unit: weightRoomUnitForType(measurementType),
    active: true,
    defaultTargetStyle: targetStyle,
    performanceDirection: defaultPerformanceDirection(name, measurementType, targetStyle),
    targetSets: measurementType === "RPE_ONLY" ? 1 : 3,
    targetReps: measurementType === "WEIGHT_REPS" || measurementType === "BODYWEIGHT_REPS" || measurementType === "REPS_ONLY" ? 8 : undefined,
  };
}

function weightRoomExerciseCategory(name: string, kind: ExerciseKind): WeightRoomExerciseCategory {
  const normalized = name.toLowerCase();
  if (kind === "Speed") return "Speed";
  if (kind === "Jump" || /(clean|power|jump)/.test(normalized)) return "Power";
  if (/(plank|core|rotation|mobility|stretch)/.test(normalized)) return "Core";
  if (/(sprint|conditioning|run|tempo)/.test(normalized)) return "Conditioning";
  if (/(bench|press|row|pull|curl|raise|shoulder|upper)/.test(normalized)) return "Upper Body";
  if (/(squat|deadlift|lunge|leg|hamstring|calf|lower)/.test(normalized)) return "Lower Body";
  return "Other";
}

function weightRoomMeasurementType(name: string): WorkoutMeasurementType {
  const normalized = name.toLowerCase();
  if (/(sled|1rm|max load|heavy single|max weight)/.test(normalized)) return "WEIGHT_ONLY";
  if (/(sprint|dash|plank|hold|timed)/.test(normalized)) return "TIME";
  if (/(jump|broad|vertical)/.test(normalized)) return "DISTANCE";
  if (/(pull up|push up|sit up|max reps|bodyweight|challenge)/.test(normalized)) return "REPS_ONLY";
  if (/(mobility|stretch|activation|warmup)/.test(normalized)) return "COMPLETION";
  if (/(rpe)/.test(normalized)) return "RPE_ONLY";
  return "WEIGHT_REPS";
}

function weightRoomUnitForType(type: WorkoutMeasurementType): WorkoutEntry["unit"] | undefined {
  if (type === "WEIGHT_REPS" || type === "WEIGHT_ONLY") return "lb";
  if (type === "BODYWEIGHT_REPS" || type === "REPS_ONLY" || type === "COUNT") return "reps";
  if (type === "TIME") return "sec";
  if (type === "DISTANCE" || type === "HEIGHT") return "in";
  return undefined;
}

function weightRoomMeasurementLabel(exercise?: WeightRoomExercise) {
  if (!exercise) return "Value";
  if (exercise.measurementType === "TIME") return "Time";
  if (exercise.measurementType === "DISTANCE") return "Distance";
  if (exercise.measurementType === "HEIGHT") return "Height";
  if (exercise.measurementType === "WEIGHT_ONLY") return "Weight";
  if (exercise.measurementType === "COMPLETION") return "Completion";
  if (exercise.measurementType === "BODYWEIGHT_REPS" || exercise.measurementType === "REPS_ONLY" || exercise.measurementType === "COUNT") return "Reps";
  return "Value";
}

function workoutMeasurementTypeLabel(type: WorkoutMeasurementType) {
  if (type === "WEIGHT_REPS") return "Weight + Reps";
  if (type === "BODYWEIGHT_REPS") return "Bodyweight Reps";
  if (type === "REPS_ONLY") return "Reps Only";
  if (type === "TIME") return "Time";
  if (type === "DISTANCE") return "Distance";
  if (type === "HEIGHT") return "Height";
  if (type === "WEIGHT_ONLY") return "Weight Only";
  if (type === "COUNT") return "Count";
  if (type === "COMPLETION") return "Completion";
  if (type === "RPE_ONLY") return "RPE Only";
  return "Custom";
}

function uniqueStrings(values: string[]) {
  return [...new Set(values.filter(Boolean))];
}

function upsertById<T extends { id: ID }>(items: T[], item: T) {
  return items.some((current) => current.id === item.id)
    ? items.map((current) => current.id === item.id ? item : current)
    : [item, ...items];
}

function applyWeightRoomSetupToData(data: AppData, payload: WeightRoomSetupPayload): AppData {
  const now = new Date().toISOString();
  const team = data.teamContext?.currentTeam;
  const profileId = data.teamContext?.profile?.id;
  const existingStations = new Map((data.weightRoomWorkoutStations ?? []).map((station) => [station.id, station]));
  const existingGroups = new Map((data.weightRoomWorkoutGroups ?? []).map((group) => [group.id, group]));
  const existingMembersByKey = new Map((data.weightRoomWorkoutGroupMembers ?? []).map((member) => [`${member.workoutId}:${member.groupId}:${member.playerId}`, member]));
  const stationRows: PersistedWeightRoomWorkoutStation[] = payload.stations.map((station, index) => {
    const existing = existingStations.get(station.id);
    return {
      id: station.id,
      workoutId: payload.workoutId,
      exerciseName: station.name,
      displayOrder: index + 1,
      targetSets: station.targetSets,
      targetReps: station.targetReps,
      targetValue: station.targetValue,
      targetStyle: station.targetStyle,
      measurementType: station.measurementType,
      performanceDirection: station.performanceDirection,
      unit: station.unit,
      notes: station.notes,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
  });
  const groupRows: PersistedWeightRoomWorkoutGroup[] = payload.groups.map((group, index) => {
    const existing = existingGroups.get(group.id);
    return {
      id: group.id,
      workoutId: payload.workoutId,
      name: group.name || `Group ${index + 1}`,
      displayOrder: index + 1,
      currentStationId: stationRows[group.stationIndex]?.id,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
  });
  const memberRows: PersistedWeightRoomWorkoutGroupMember[] = payload.groups.flatMap((group) =>
    group.playerIds.map((playerId) => {
      const existing = existingMembersByKey.get(`${payload.workoutId}:${group.id}:${playerId}`);
      return {
        id: existing?.id ?? createId("wrgm"),
        workoutId: payload.workoutId,
        groupId: group.id,
        playerId,
        participantStatus: "ASSIGNED",
        createdAt: existing?.createdAt ?? now,
        updatedAt: now,
      };
    }),
  );
  const nextExercises = mergePersistedExerciseDefinitions(data.weightRoomExercises ?? [], payload.exerciseDefinitions, team?.organizationId, now);
  const savedExercisePresets = payload.exercisePresets.filter((preset) => isUuid(preset.id));
  const savedGroupPresets = payload.groupPresets.filter((preset) => isUuid(preset.id));
  const nextExercisePresets: PersistedWeightRoomExercisePreset[] = savedExercisePresets.map((preset) => {
    const existing = (data.weightRoomExercisePresets ?? []).find((item) => item.id === preset.id);
    return {
      id: preset.id,
      organizationId: team?.organizationId,
      teamId: team?.teamId,
      name: preset.name,
      archivedAt: preset.archived ? now : existing?.archivedAt,
      createdBy: existing?.createdBy ?? profileId,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
  });
  const existingExercisePresetItemByKey = new Map((data.weightRoomExercisePresetItems ?? []).map((item) => [`${item.presetId}:${item.exerciseName.toLowerCase()}`, item]));
  const nextExercisePresetItems: PersistedWeightRoomExercisePresetItem[] = savedExercisePresets.flatMap((preset) =>
    preset.stations.map((station, index) => {
      const existing = existingExercisePresetItemByKey.get(`${preset.id}:${station.name.toLowerCase()}`);
      return {
        id: existing?.id ?? createId("wepi"),
        presetId: preset.id,
        exerciseName: station.name,
        displayOrder: index + 1,
        targetSets: station.targetSets,
        targetReps: station.targetReps,
        targetValue: station.targetValue,
        targetStyle: station.targetStyle,
        measurementType: station.measurementType,
        performanceDirection: station.performanceDirection,
        unit: station.unit,
        notes: station.notes,
        createdAt: existing?.createdAt ?? now,
        updatedAt: now,
      };
    }),
  );
  const nextGroupPresets: PersistedWeightRoomGroupPreset[] = savedGroupPresets.map((preset) => {
    const existing = (data.weightRoomGroupPresets ?? []).find((item) => item.id === preset.id);
    return {
      id: preset.id,
      organizationId: team?.organizationId,
      teamId: team?.teamId,
      name: preset.name,
      archivedAt: preset.archived ? now : existing?.archivedAt,
      createdBy: existing?.createdBy ?? profileId,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
  });
  const existingGroupPresetGroupByKey = new Map((data.weightRoomGroupPresetGroups ?? []).map((group) => [`${group.presetId}:${group.displayOrder}:${group.name.toLowerCase()}`, group]));
  const existingGroupPresetMemberByKey = new Map((data.weightRoomGroupPresetMembers ?? []).map((member) => [`${member.presetId}:${member.groupId}:${member.playerId}`, member]));
  const nextGroupPresetGroups: PersistedWeightRoomGroupPresetGroup[] = [];
  const nextGroupPresetMembers: PersistedWeightRoomGroupPresetMember[] = [];
  for (const preset of savedGroupPresets) {
    preset.groups.forEach((group, index) => {
      const existingGroup = existingGroupPresetGroupByKey.get(`${preset.id}:${index + 1}:${group.name.toLowerCase()}`);
      const groupId = existingGroup?.id ?? (isUuid(group.id) ? group.id : createId("wgpg"));
      nextGroupPresetGroups.push({
        id: groupId,
        presetId: preset.id,
        name: group.name || `Group ${index + 1}`,
        displayOrder: index + 1,
        createdAt: existingGroup?.createdAt ?? now,
        updatedAt: now,
      });
      group.playerIds.forEach((playerId) => {
        const existingMember = existingGroupPresetMemberByKey.get(`${preset.id}:${groupId}:${playerId}`);
        nextGroupPresetMembers.push({
          id: existingMember?.id ?? createId("wgpm"),
          presetId: preset.id,
          groupId,
          playerId,
          createdAt: existingMember?.createdAt ?? now,
          updatedAt: now,
        });
      });
    });
  }
  return {
    ...data,
    weightRoomExercises: nextExercises,
    weightRoomWorkoutStations: [
      ...(data.weightRoomWorkoutStations ?? []).filter((station) => station.workoutId !== payload.workoutId),
      ...stationRows,
    ],
    weightRoomWorkoutGroups: [
      ...(data.weightRoomWorkoutGroups ?? []).filter((group) => group.workoutId !== payload.workoutId),
      ...groupRows,
    ],
    weightRoomWorkoutGroupMembers: [
      ...(data.weightRoomWorkoutGroupMembers ?? []).filter((member) => member.workoutId !== payload.workoutId),
      ...memberRows,
    ],
    weightRoomExercisePresets: nextExercisePresets,
    weightRoomExercisePresetItems: nextExercisePresetItems,
    weightRoomGroupPresets: nextGroupPresets,
    weightRoomGroupPresetGroups: nextGroupPresetGroups,
    weightRoomGroupPresetMembers: nextGroupPresetMembers,
  };
}

function mergePersistedExerciseDefinitions(existing: PersistedWeightRoomExercise[], exercises: WeightRoomExercise[], organizationId: ID | undefined, now: string) {
  const byName = new Map(existing.map((exercise) => [exercise.name.toLowerCase(), exercise]));
  for (const exercise of exercises) {
    const current = byName.get(exercise.name.toLowerCase());
    const targetStyle = exercise.defaultTargetStyle ?? defaultTargetStyle(exercise.name, exercise.measurementType);
    byName.set(exercise.name.toLowerCase(), {
      id: current?.id ?? createId("wre"),
      organizationId: current?.organizationId ?? organizationId,
      name: exercise.name,
      kind: exercise.kind,
      category: exercise.category,
      measurementType: exercise.measurementType,
      performanceDirection: exercise.performanceDirection ?? defaultPerformanceDirection(exercise.name, exercise.measurementType, targetStyle),
      defaultTargetStyle: targetStyle,
      unit: exercise.unit,
      equipment: exercise.equipment,
      active: exercise.active,
      archivedAt: current?.archivedAt,
      createdAt: current?.createdAt ?? now,
      updatedAt: now,
    });
  }
  return [...byName.values()];
}

function optionalNumber(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function optionalTimeValue(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  if (trimmed.includes(":")) {
    const [minutesRaw, secondsRaw = "0"] = trimmed.split(":");
    const minutes = Number(minutesRaw);
    const seconds = Number(secondsRaw);
    if (Number.isFinite(minutes) && Number.isFinite(seconds)) return (minutes * 60) + seconds;
  }
  return optionalNumber(trimmed);
}

function optionalDistanceValue(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  const feetInches = trimmed.match(/^(\d+)\s*(?:'|ft)\s*(\d+(?:\.\d+)?)?/i);
  if (feetInches) {
    const feet = Number(feetInches[1]);
    const inches = Number(feetInches[2] ?? 0);
    if (Number.isFinite(feet) && Number.isFinite(inches)) return (feet * 12) + inches;
  }
  return optionalNumber(trimmed.replace(/["in\s]/gi, ""));
}

function cleanWorkoutMeasurementDraft(value: string, measurementType: WorkoutMeasurementType) {
  if (measurementType === "TIME") return value.replace(/[^0-9:.]/g, "");
  if (measurementType === "DISTANCE" || measurementType === "HEIGHT") return value.replace(/[^0-9.'"\s]/g, "");
  return value.replace(/[^0-9.]/g, "");
}

function entrySessionDate(data: AppData, entry: WorkoutEntry) {
  return data.workoutSessions.find((session) => session.id === entry.sessionId)?.date ?? entry.createdAt.slice(0, 10);
}

function workoutEntryPersistedStation(data: AppData, entry: WorkoutEntry) {
  const sessionDate = entrySessionDate(data, entry);
  const workoutsForSession = (data.weightRoomWorkouts ?? [])
    .filter((workout) => workout.date === sessionDate && workout.status !== "CANCELLED")
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt) || right.createdAt.localeCompare(left.createdAt));
  const stationRows = (data.weightRoomWorkoutStations ?? []).filter((station) => !station.archivedAt);
  for (const workout of workoutsForSession) {
    const station = stationRows
      .filter((item) => item.workoutId === workout.id && item.exerciseName.toLowerCase() === entry.exercise.toLowerCase())
      .sort((left, right) => left.displayOrder - right.displayOrder)[0];
    if (station) return station;
  }
  return undefined;
}

function workoutEntryStationContext(
  data: AppData,
  entry: WorkoutEntry,
  exerciseDefinition?: WeightRoomExercise,
): Pick<ActiveWorkoutStation, "measurementType" | "targetStyle" | "unit" | "performanceDirection"> | undefined {
  const station = workoutEntryPersistedStation(data, entry);
  const measurementType = station?.measurementType ?? exerciseDefinition?.measurementType;
  if (!measurementType) return undefined;
  const targetStyle = station?.targetStyle ?? exerciseDefinition?.defaultTargetStyle ?? defaultTargetStyle(entry.exercise, measurementType);
  return {
    measurementType,
    targetStyle,
    unit: station?.unit ?? exerciseDefinition?.unit,
    performanceDirection: station?.performanceDirection ?? exerciseDefinition?.performanceDirection ?? defaultPerformanceDirection(entry.exercise, measurementType, targetStyle),
  };
}

function workoutEntryMatchesResultMode(
  data: AppData,
  entry: WorkoutEntry,
  targetStyle: WorkoutTargetStyle | undefined,
  exerciseDefinition?: WeightRoomExercise,
) {
  if (!targetStyle) return true;
  return workoutEntryStationContext(data, entry, exerciseDefinition)?.targetStyle === targetStyle;
}

function formatWorkoutEntryValue(entry: WorkoutEntry) {
  if (typeof entry.weight === "number" && typeof entry.reps === "number") return `${formatNumber(entry.weight, 0)} lb x ${entry.reps}`;
  if (typeof entry.weight === "number") return `${formatNumber(entry.weight, 0)} lb`;
  if (typeof entry.value === "number" && entry.unit === "sec") return formatSecondsValue(entry.value);
  if (typeof entry.value === "number" && entry.unit === "in") return formatInchesValue(entry.value);
  if (typeof entry.value === "number") return `${formatNumber(entry.value, 1)}${entry.unit ? ` ${entry.unit}` : ""}`;
  if (typeof entry.reps === "number") return `${entry.reps} reps`;
  return "--";
}

function formatWorkoutEntryValueForStation(entry: WorkoutEntry, station?: Pick<ActiveWorkoutStation, "measurementType" | "targetStyle" | "unit">) {
  if (!station) return formatWorkoutEntryValue(entry);
  if (station.measurementType === "WEIGHT_REPS") {
    if (typeof entry.weight === "number" && typeof entry.reps === "number") return `${formatNumber(entry.weight, 0)} lb x ${entry.reps}`;
    if (typeof entry.weight === "number") return `${formatNumber(entry.weight, 0)} lb`;
    if (typeof entry.reps === "number") return `${entry.reps} reps`;
    return "--";
  }
  if (station.measurementType === "WEIGHT_ONLY") {
    const value = entry.weight ?? entry.value;
    return typeof value === "number" ? `${formatNumber(value, 0)} lb` : "--";
  }
  if (station.measurementType === "BODYWEIGHT_REPS" || station.measurementType === "REPS_ONLY" || station.measurementType === "COUNT") {
    const value = entry.reps ?? entry.value;
    return typeof value === "number" ? `${formatNumber(value, 0)} reps` : "--";
  }
  if (station.measurementType === "TIME") {
    return typeof entry.value === "number" ? formatSecondsValue(entry.value) : "--";
  }
  if (station.measurementType === "DISTANCE" || station.measurementType === "HEIGHT") {
    return typeof entry.value === "number" ? formatInchesValue(entry.value) : "--";
  }
  if (station.measurementType === "COMPLETION" || station.targetStyle === "Completion") {
    return (entry.status ?? "Completed") === "Skipped" ? "Skipped" : "Completed";
  }
  if (station.measurementType === "RPE_ONLY") {
    return typeof entry.rpe === "number" ? `${formatNumber(entry.rpe, 1)} RPE` : typeof entry.value === "number" ? formatNumber(entry.value, 1) : "--";
  }
  return formatWorkoutEntryValue(entry);
}

function formatSecondsValue(value: number) {
  if (value >= 60) {
    const minutes = Math.floor(value / 60);
    const seconds = Math.round(value % 60).toString().padStart(2, "0");
    return `${minutes}:${seconds}`;
  }
  return `${formatNumber(value, 2)} sec`;
}

function formatInchesValue(value: number) {
  if (value >= 24) {
    const feet = Math.floor(value / 12);
    const inches = Math.round(value - feet * 12);
    return `${feet}'${inches}"`;
  }
  return `${formatNumber(value, 1)} in`;
}

function formatWorkoutVolume(value: number) {
  if (!value) return "--";
  if (value >= 1000) return `${formatCompactNumber(value)} lbs`;
  return `${formatNumber(value, 0)} lbs`;
}

function latestBodyWeight(data: AppData, playerId: ID, throughDate?: string, exactDateOnly = false) {
  const sessions = data.workoutSessions
    .filter((session) => session.playerId === playerId && typeof session.bodyWeight === "number")
    .filter((session) => exactDateOnly ? session.date === throughDate : !throughDate || session.date <= throughDate)
    .sort((left, right) => right.date.localeCompare(left.date) || right.updatedAt.localeCompare(left.updatedAt));
  return sessions[0]?.bodyWeight;
}

function previousBodyWeight(data: AppData, playerId: ID, beforeDate: string) {
  const sessions = data.workoutSessions
    .filter((session) => session.playerId === playerId && typeof session.bodyWeight === "number" && session.date < beforeDate)
    .sort((left, right) => right.date.localeCompare(left.date) || right.updatedAt.localeCompare(left.updatedAt));
  return sessions[0]?.bodyWeight;
}

function latestWeeklyBodyWeight(data: AppData, playerId: ID, weekOf: string, throughDate: string) {
  const sessions = data.workoutSessions
    .filter((session) => session.playerId === playerId && typeof session.bodyWeight === "number")
    .filter((session) => (session.weekOf || weekStart(session.date)) === weekOf && session.date <= throughDate)
    .sort((left, right) => right.date.localeCompare(left.date) || right.updatedAt.localeCompare(left.updatedAt));
  return sessions[0]?.bodyWeight;
}

function latestBodyWeightBeforeWeek(data: AppData, playerId: ID, weekOf: string) {
  const sessions = data.workoutSessions
    .filter((session) => session.playerId === playerId && typeof session.bodyWeight === "number")
    .filter((session) => (session.weekOf || weekStart(session.date)) < weekOf)
    .sort((left, right) => right.date.localeCompare(left.date) || right.updatedAt.localeCompare(left.updatedAt));
  return sessions[0]?.bodyWeight;
}

function startingBodyWeight(data: AppData, playerId: ID) {
  const sessions = data.workoutSessions
    .filter((session) => session.playerId === playerId && typeof session.bodyWeight === "number")
    .sort((left, right) => left.date.localeCompare(right.date) || left.createdAt.localeCompare(right.createdAt));
  return sessions[0]?.bodyWeight;
}

function teamLocation(team?: TeamOption) {
  return [team?.city, team?.state].filter(Boolean).join(", ");
}

function buildRecentWeightRoomWorkouts(data: AppData, players: Player[]): WeightRoomWorkoutSummary[] {
  const playerIds = new Set(players.map((player) => player.id));
  const byDate = new Map<string, WorkoutSession[]>();
  for (const session of data.workoutSessions.filter((item) => playerIds.has(item.playerId))) {
    const group = byDate.get(session.date) ?? [];
    group.push(session);
    byDate.set(session.date, group);
  }
  return [...byDate.entries()]
    .sort(([left], [right]) => right.localeCompare(left))
    .map(([date, sessions]) => {
      const sessionIds = new Set(sessions.map((session) => session.id));
      const entries = data.workoutEntries.filter((entry) => sessionIds.has(entry.sessionId));
      const liftEvent = (data.scheduleEvents ?? []).find((event) => event.eventType === "Lift" && dateKeyFromIso(event.startAt) === date);
      return {
        date,
        title: liftEvent?.title ?? "Team Lift",
        location: liftEvent?.location,
        startAt: liftEvent?.startAt,
        athletes: new Set(sessions.map((session) => session.playerId)).size,
        sets: entries.filter((entry) => (entry.status ?? "Completed") !== "Skipped").length,
        volume: entries.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0),
        completed: sessions.length > 0 && sessions.every((session) => session.completed),
      };
    });
}

function buildWeightRoomTeamOverview(data: AppData, players: Player[], date: string) {
  const playerIds = new Set(players.map((player) => player.id));
  const week = weekStart(date);
  const previousWeek = shiftDateKey(week, -7);
  const sessionsThisWeek = data.workoutSessions.filter((session) => playerIds.has(session.playerId) && (session.weekOf || weekStart(session.date)) === week);
  const completedSessionsThisWeek = sessionsThisWeek.filter((session) => session.completed);
  const completedSessionIds = new Set(completedSessionsThisWeek.map((session) => session.id));
  const entriesThisWeek = data.workoutEntries.filter((entry) => completedSessionIds.has(entry.sessionId) && (entry.status ?? "Completed") !== "Skipped");
  const sessionsLastWeek = data.workoutSessions.filter((session) => playerIds.has(session.playerId) && (session.weekOf || weekStart(session.date)) === previousWeek && session.completed);
  const lastWeekSessionIds = new Set(sessionsLastWeek.map((session) => session.id));
  const entriesLastWeek = data.workoutEntries.filter((entry) => lastWeekSessionIds.has(entry.sessionId) && (entry.status ?? "Completed") !== "Skipped");
  const completedAthletes = new Set(completedSessionsThisWeek.map((session) => session.playerId)).size;
  const completedWorkoutCount = new Set(completedSessionsThisWeek.map((session) => session.date)).size;
  const volume = entriesThisWeek.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0);
  const lastWeekVolume = entriesLastWeek.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0);
  const leaderboardThisWeek = buildScoredWeightRoomLeaderboard(players, data.workoutSessions, data.workoutEntries, "This Week", date);
  const trendValues = leaderboardThisWeek.map((row) => row.progressPct).filter((value) => Number.isFinite(value) && value !== 0);
  const improvementEntries = entriesThisWeek.filter(isWorkoutEntryImprovement);
  const nextLift = buildScheduleItems(data)
    .filter((item) => item.eventType === "Lift" && item.status !== "Completed" && item.status !== "Cancelled" && isUpcomingScheduleItem(item))
    .sort((left, right) => Date.parse(left.startAt) - Date.parse(right.startAt))[0];
  return {
    athletes: players.length,
    completedAthletes,
    completedWorkoutCount,
    workoutsThisWeek: new Set(sessionsThisWeek.map((session) => session.date)).size,
    sets: entriesThisWeek.reduce((sum, entry) => sum + Math.max(1, entry.sets ?? 1), 0),
    volume,
    completionPct: players.length ? pct(completedAthletes, players.length) : 0,
    volumeChangePct: completedWorkoutCount > 1 && lastWeekVolume > 0 ? ((volume - lastWeekVolume) / lastWeekVolume) * 100 : undefined,
    strengthTrendPct: trendValues.length ? trendValues.reduce((sum, value) => sum + value, 0) / trendValues.length : undefined,
    improvingAthletes: new Set(improvementEntries.map((entry) => entry.playerId)).size,
    trackedImprovements: improvementEntries.length,
    nextLift,
  };
}

function formatWeightRoomSessionMeta(date: string, startAt?: string) {
  return [shortDate(date), startAt ? formatTime(startAt) : undefined].filter(Boolean).join(" - ");
}

function shiftDateKey(dateKey: string, days: number) {
  const date = parseDateKey(dateKey) ?? new Date(`${dateKey}T12:00:00`);
  date.setDate(date.getDate() + days);
  return localDateKey(date);
}

function isWorkoutEntryImprovement(entry: WorkoutEntry) {
  if (!entry.priorValue) return false;
  const current = entry.weight ?? entry.value ?? entry.reps ?? 0;
  const prior = entry.priorValue;
  if (!current || !prior) return false;
  const timeBased = entry.kind === "Speed" || entry.unit === "sec";
  return timeBased ? current < prior : current > prior;
}

function buildWeightRoomPlayerProfile(data: AppData, player: Player) {
  const sessions = data.workoutSessions.filter((session) => session.playerId === player.id).sort((left, right) => right.date.localeCompare(left.date));
  const entries = data.workoutEntries.filter((entry) => entry.playerId === player.id);
  const today = todayKey();
  const week = weekStart(today);
  const previousWeek = shiftDateKey(week, -7);
  const sessionsThisWeek = sessions.filter((session) => (session.weekOf || weekStart(session.date)) === week);
  const sessionsPreviousWeek = sessions.filter((session) => (session.weekOf || weekStart(session.date)) === previousWeek);
  const sessionIdsThisWeek = new Set(sessionsThisWeek.map((session) => session.id));
  const sessionIdsPreviousWeek = new Set(sessionsPreviousWeek.map((session) => session.id));
  const entriesThisWeek = entries.filter((entry) => sessionIdsThisWeek.has(entry.sessionId) && (entry.status ?? "Completed") !== "Skipped");
  const entriesPreviousWeek = entries.filter((entry) => sessionIdsPreviousWeek.has(entry.sessionId) && (entry.status ?? "Completed") !== "Skipped");
  const score = buildScoredWeightRoomLeaderboard([player], data.workoutSessions, data.workoutEntries, "This Week", today)[0]
    ?? buildScoredWeightRoomLeaderboard([player], data.workoutSessions, data.workoutEntries, "This Season", today)[0];
  const currentWeight = latestBodyWeight(data, player.id);
  const previousWeight = previousBodyWeight(data, player.id, today);
  const volume = entriesThisWeek.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0);
  const previousVolume = entriesPreviousWeek.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0);
  const setCount = entriesThisWeek.reduce((sum, entry) => sum + Math.max(1, entry.sets ?? 1), 0);
  const previousSetCount = entriesPreviousWeek.reduce((sum, entry) => sum + Math.max(1, entry.sets ?? 1), 0);
  const nextLift = buildScheduleItems(data)
    .filter((item) => item.eventType === "Lift" && item.status !== "Completed" && item.status !== "Cancelled" && isUpcomingScheduleItem(item))
    .sort((left, right) => Date.parse(left.startAt) - Date.parse(right.startAt))[0];
  const bodyWeights = sessions
    .filter((session) => typeof session.bodyWeight === "number")
    .slice()
    .reverse()
    .map((session) => session.bodyWeight ?? 0);
  const exerciseTrends = uniqueStrings(entries.map((entry) => entry.exercise)).map((exercise) => trendForExercise(entries.filter((entry) => entry.exercise === exercise))).filter((trend) => trend.samples > 1);
  return {
    workoutsThisWeek: new Set(sessionsThisWeek.map((session) => session.date)).size,
    completedWorkoutsThisWeek: new Set(sessionsThisWeek.filter((session) => session.completed).map((session) => session.date)).size,
    scheduledWorkoutsThisWeek: new Set(sessionsThisWeek.map((session) => session.date)).size,
    volume,
    volumeChangePct: previousVolume > 0 ? ((volume - previousVolume) / previousVolume) * 100 : undefined,
    sets: setCount,
    setChange: sessionsPreviousWeek.length || previousSetCount ? setCount - previousSetCount : undefined,
    currentWeight,
    weightChange: typeof currentWeight === "number" && typeof previousWeight === "number" ? currentWeight - previousWeight : undefined,
    score,
    weightTrend: bodyWeights,
    exerciseTrends,
    nextLift,
  };
}

function buildWeightRoomPlayerExerciseRows(data: AppData, player: Player, exercises: WeightRoomExercise[]) {
  const week = weekStart(todayKey());
  const previousWeek = shiftDateKey(week, -7);
  const sessionsById = new Map(data.workoutSessions.map((session) => [session.id, session]));
  return exercises.map((exercise) => {
    const exerciseEntries = data.workoutEntries
      .filter((entry) => entry.playerId === player.id && entry.exercise === exercise.name && (entry.status ?? "Completed") !== "Skipped")
      .sort((left, right) => entrySessionDate(data, right).localeCompare(entrySessionDate(data, left)) || right.createdAt.localeCompare(left.createdAt));
    const currentWeekEntries = exerciseEntries.filter((entry) => (sessionsById.get(entry.sessionId)?.weekOf || weekStart(entrySessionDate(data, entry))) === week);
    const previousWeekEntries = exerciseEntries.filter((entry) => (sessionsById.get(entry.sessionId)?.weekOf || weekStart(entrySessionDate(data, entry))) === previousWeek);
    const current = bestWorkoutEntry(currentWeekEntries);
    const previous = bestWorkoutEntry(previousWeekEntries);
    const start = exerciseEntries.slice().sort((left, right) => entrySessionDate(data, left).localeCompare(entrySessionDate(data, right)) || left.createdAt.localeCompare(right.createdAt))[0];
    const best = bestWorkoutEntry(exerciseEntries);

    return {
      exercise,
      current,
      previous,
      start,
      best,
      entries: exerciseEntries,
      sets: exerciseEntries.length,
      volume: exerciseEntries.reduce((sum, entry) => sum + workoutEntryVolume(entry), 0),
      changeLast: workoutEntryPercentDelta(current, previous),
      changeStart: workoutEntryPercentDelta(current, start),
    };
  });
}

function buildWeightRoomWorkoutRows(data: AppData, session: WorkoutSession, entries: WorkoutEntry[]) {
  const exerciseLibrary = buildWeightRoomExerciseLibrary(data);
  const exerciseByName = new Map(exerciseLibrary.map((exercise) => [exercise.name.toLowerCase(), exercise]));
  return entries
    .filter((entry) => (entry.status ?? "Completed") !== "Skipped")
    .map((entry) => {
      const exercise = exerciseByName.get(entry.exercise.toLowerCase()) ?? makeWeightRoomExercise(entry.exercise);
      const history = data.workoutEntries
        .filter((item) => item.playerId === entry.playerId && item.exercise === entry.exercise && item.id !== entry.id)
        .filter((item) => workoutEntriesComparable(entry, item))
        .filter((item) => entrySessionDate(data, item) <= session.date)
        .sort((left, right) => entrySessionDate(data, right).localeCompare(entrySessionDate(data, left)) || right.createdAt.localeCompare(left.createdAt));
      const previous = history.find((item) => entrySessionDate(data, item) < session.date);
      const start = data.workoutEntries
        .filter((item) => item.playerId === entry.playerId && item.exercise === entry.exercise)
        .filter((item) => workoutEntriesComparable(entry, item))
        .sort((left, right) => entrySessionDate(data, left).localeCompare(entrySessionDate(data, right)) || left.createdAt.localeCompare(right.createdAt))[0];
      return {
        entry,
        exercise,
        previous,
        start,
        changeLast: workoutEntryPercentDelta(entry, previous),
        changeStart: workoutEntryPercentDelta(entry, start),
      };
    });
}

function buildWeightRoomPlayerProgressRows(data: AppData, player: Player, exercises: WeightRoomExercise[]) {
  return buildWeightRoomPlayerExerciseRows(data, player, exercises)
    .filter((row) => row.sets > 0)
    .map((row) => {
      const trend = trendForExercise(row.entries);
      const changePct = typeof row.changeStart === "number" ? row.changeStart : trend.samples > 1 ? trend.changePct : undefined;
      return { ...row, changePct };
    })
    .sort((left, right) => sortableDelta(right.changePct) - sortableDelta(left.changePct) || left.exercise.name.localeCompare(right.exercise.name));
}

function sortWeightRoomExerciseRows(rows: ReturnType<typeof buildWeightRoomPlayerExerciseRows>, sort: WeightRoomSortState<WeightRoomExerciseSortKey>) {
  return rows.slice().sort((left, right) => {
    let result = 0;
    if (sort.key === "exercise") result = left.exercise.name.localeCompare(right.exercise.name);
    if (sort.key === "current") result = compareOptionalNumbers(workoutEntrySortableValue(left.current), workoutEntrySortableValue(right.current), "asc");
    if (sort.key === "previous") result = compareOptionalNumbers(workoutEntrySortableValue(left.previous), workoutEntrySortableValue(right.previous), "asc");
    if (sort.key === "changeLast") result = compareOptionalNumbers(left.changeLast, right.changeLast, "asc");
    if (sort.key === "start") result = compareOptionalNumbers(workoutEntrySortableValue(left.start), workoutEntrySortableValue(right.start), "asc");
    if (sort.key === "changeStart") result = compareOptionalNumbers(left.changeStart, right.changeStart, "asc");
    if (sort.key === "best") result = compareOptionalNumbers(workoutEntrySortableValue(left.best), workoutEntrySortableValue(right.best), "asc");
    if (sort.key === "sets") result = compareOptionalNumbers(left.sets, right.sets, "asc");
    return applySortDirection(result, sort.direction) || left.exercise.name.localeCompare(right.exercise.name);
  });
}

function sortWeightRoomWorkoutRows(rows: ReturnType<typeof buildWeightRoomWorkoutRows>, sort: WeightRoomSortState<WeightRoomWorkoutSortKey>) {
  return rows.slice().sort((left, right) => {
    let result = 0;
    if (sort.key === "exercise") result = left.entry.exercise.localeCompare(right.entry.exercise);
    if (sort.key === "set") result = compareOptionalNumbers(left.entry.setNumber ?? left.entry.sets, right.entry.setNumber ?? right.entry.sets, "asc");
    if (sort.key === "current") result = compareOptionalNumbers(workoutEntrySortableValue(left.entry), workoutEntrySortableValue(right.entry), "asc");
    if (sort.key === "previous") result = compareOptionalNumbers(workoutEntrySortableValue(left.previous), workoutEntrySortableValue(right.previous), "asc");
    if (sort.key === "changeLast") result = compareOptionalNumbers(left.changeLast, right.changeLast, "asc");
    if (sort.key === "start") result = compareOptionalNumbers(workoutEntrySortableValue(left.start), workoutEntrySortableValue(right.start), "asc");
    if (sort.key === "changeStart") result = compareOptionalNumbers(left.changeStart, right.changeStart, "asc");
    if (sort.key === "rpe") result = compareOptionalNumbers(left.entry.rpe, right.entry.rpe, "asc");
    return applySortDirection(result, sort.direction)
      || left.entry.exercise.localeCompare(right.entry.exercise)
      || compareOptionalNumbers(left.entry.setNumber ?? left.entry.sets, right.entry.setNumber ?? right.entry.sets, "asc")
      || left.entry.createdAt.localeCompare(right.entry.createdAt);
  });
}

function groupWeightRoomWorkoutRows(rows: ReturnType<typeof buildWeightRoomWorkoutRows>) {
  const groups: Array<{ exercise: string; rows: ReturnType<typeof buildWeightRoomWorkoutRows> }> = [];
  for (const row of rows) {
    const latest = groups[groups.length - 1];
    if (latest?.exercise === row.entry.exercise) latest.rows.push(row);
    else groups.push({ exercise: row.entry.exercise, rows: [row] });
  }
  return groups;
}

function nextWeightRoomSortState<K extends string>(current: WeightRoomSortState<K>, key: K, fallback: WeightRoomSortState<K>): WeightRoomSortState<K> {
  if (current.key !== key) return { key, direction: "asc" };
  if (current.direction === "asc") return { key, direction: "desc" };
  return fallback;
}

function compareOptionalNumbers(left: number | undefined, right: number | undefined, direction: SortDirection) {
  const hasLeft = typeof left === "number" && Number.isFinite(left);
  const hasRight = typeof right === "number" && Number.isFinite(right);
  if (!hasLeft && !hasRight) return 0;
  if (!hasLeft) return 1;
  if (!hasRight) return -1;
  return direction === "asc" ? left - right : right - left;
}

function applySortDirection(value: number, direction: SortDirection) {
  return direction === "asc" ? value : -value;
}

function workoutEntriesComparable(current: WorkoutEntry, baseline: WorkoutEntry) {
  if (current.exercise !== baseline.exercise) return false;
  if (current.unit && baseline.unit && current.unit !== baseline.unit) return false;
  if (typeof current.weight === "number" || typeof baseline.weight === "number") {
    return typeof current.weight === "number" && typeof baseline.weight === "number";
  }
  if (typeof current.value === "number" || typeof baseline.value === "number") {
    return typeof current.value === "number" && typeof baseline.value === "number";
  }
  if (typeof current.reps === "number" || typeof baseline.reps === "number") {
    return typeof current.reps === "number" && typeof baseline.reps === "number";
  }
  return true;
}

function initialWeightRoomAthleteTab(): WeightRoomAthleteTab {
  if (typeof window === "undefined") return "Overview";
  const requested = new URLSearchParams(window.location.search).get("athleteView");
  return WEIGHT_ROOM_ATHLETE_TABS.find((tab) => tab.toLowerCase() === requested?.toLowerCase()) ?? "Overview";
}

function syncWeightRoomAthleteUrl(playerId: ID, tab: WeightRoomAthleteTab) {
  if (typeof window === "undefined") return;
  const url = new URL(window.location.href);
  url.searchParams.set("view", "weights");
  url.searchParams.set("athlete", playerId);
  url.searchParams.set("athleteView", tab.toLowerCase());
  const nextUrl = `${url.pathname}${url.search}${url.hash}`;
  const currentUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;
  if (nextUrl !== currentUrl) window.history.replaceState({}, "", nextUrl);
}

function firstName(player: Player) {
  return player.name.split(" ")[0] ?? player.name;
}

function buildWeightRoomAthleteFocus(player: Player, profile: ReturnType<typeof buildWeightRoomPlayerProfile>) {
  if (!profile.sets) {
    return {
      title: "Build workout history",
      body: "Not enough workout history yet to identify a focus area.",
    };
  }
  const trends = profile.exerciseTrends.slice().sort((left, right) => left.changePct - right.changePct);
  const weakest = trends[0];
  const strongest = trends[trends.length - 1];
  if (weakest && weakest.changePct < -1) {
    return {
      title: `Stabilize ${weakest.exercise}`,
      body: `${weakest.exercise} is down ${formatNumber(Math.abs(weakest.changePct), 1)}% across comparable logged sets.`,
    };
  }
  if (weakest && Math.abs(weakest.changePct) <= 1) {
    return {
      title: `Move ${weakest.exercise} forward`,
      body: `${weakest.exercise} has held nearly flat across recent comparable sessions.`,
    };
  }
  if (strongest && strongest.changePct > 1) {
    return {
      title: `Keep building ${strongest.exercise}`,
      body: `${firstName(player)} is trending up ${formatNumber(strongest.changePct, 1)}% on ${strongest.exercise}.`,
    };
  }
  return {
    title: "Keep logging comparable sets",
    body: "Consistent weekly workout entries will make the next focus recommendation more specific.",
  };
}

function buildWeightRoomProgressInsight(player: Player, rows: ReturnType<typeof buildWeightRoomPlayerProgressRows>, score?: WeightLeaderResult) {
  if (!score && !rows.length) return "Log two comparable workouts, then use the same exercises and units so the system can identify the next lift to push.";
  const improving = rows.filter((row) => typeof row.changePct === "number" && row.changePct > 1);
  const flat = rows.filter((row) => typeof row.changePct === "number" && Math.abs(row.changePct) <= 1);
  const declining = rows.filter((row) => typeof row.changePct === "number" && row.changePct < -1);
  if (improving.length && flat.length) {
    return `Next best move: keep ${improving[0].exercise.name} progressing, then give ${flat[0].exercise.name} a small overload target so it stops sitting at baseline.`;
  }
  if (improving.length) return `Next best move: build the week around ${improving[0].exercise.name}, then add one secondary lift with a clear load or rep target.`;
  if (declining.length) return `Next best move: reset ${declining[0].exercise.name} with a manageable target and check whether load, recovery, or missed sets caused the dip.`;
  const lowestScorePart = score?.breakdown?.slice().sort((left, right) => (left.value / Math.max(1, left.max)) - (right.value / Math.max(1, right.max)))[0];
  if (lowestScorePart) return `Next best move: attack ${lowestScorePart.label.toLowerCase()} first. Keep the completed-workout rhythm, but add one measurable overload target to create a cleaner progress signal.`;
  if (score) return `Next best move: keep the workout rhythm, then add one comparable set target so ${firstName(player)} can turn the ${score.score}/100 score into visible week-over-week movement.`;
  return "Log another comparable workout so the next recommendation can point to a specific lift, load, and trend.";
}

function formatWeightRoomTrend(value: number | undefined, suffix: string) {
  if (typeof value !== "number") return "No prior week";
  if (Math.abs(value) < 0.05) return "No change";
  return `${value > 0 ? "+" : ""}${formatNumber(value, 0)}% ${suffix}`;
}

function formatSignedCount(value: number | undefined, suffix: string) {
  if (typeof value !== "number") return "No prior week";
  if (value === 0) return "No change";
  return `${value > 0 ? "+" : ""}${value} ${suffix}`;
}

function formatSignedWeight(value: number) {
  if (Math.abs(value) < 0.05) return "No change";
  return `${value > 0 ? "+" : ""}${formatNumber(value, 1)} lb`;
}

function formatRelativeWorkoutDate(date: string) {
  const today = todayKey();
  if (date === today) return "Today";
  if (date === shiftDateKey(today, 1)) return "Tomorrow";
  return shortDate(date);
}

function bestWorkoutEntry(entries: WorkoutEntry[]) {
  return entries.slice().sort((left, right) => workoutEntryComparableForDisplay(right) - workoutEntryComparableForDisplay(left))[0];
}

function workoutEntrySortableValue(entry?: WorkoutEntry) {
  return entry ? workoutEntryComparableForDisplay(entry) : Number.NEGATIVE_INFINITY;
}

function workoutEntryComparableForDisplay(entry: WorkoutEntry) {
  if (entry.unit === "sec" && typeof entry.value === "number") return -entry.value;
  return estimatedOneRepMax(entry.weight, entry.reps) ?? entry.weight ?? entry.value ?? entry.reps ?? 0;
}

function workoutEntryPercentDelta(current?: WorkoutEntry, baseline?: WorkoutEntry) {
  if (!current || !baseline || current.id === baseline.id || !workoutEntriesComparable(current, baseline)) return undefined;
  const currentValue = workoutEntryComparableForDisplay(current);
  const baselineValue = workoutEntryComparableForDisplay(baseline);
  if (!currentValue || !baselineValue) return undefined;
  return ((currentValue - baselineValue) / Math.abs(baselineValue)) * 100;
}

function sortableDelta(value?: number) {
  return typeof value === "number" ? value : Number.NEGATIVE_INFINITY;
}

function formatWorkoutDelta(value?: number) {
  if (typeof value !== "number") return "--";
  if (Math.abs(value) < 0.05) return "0%";
  return `${value > 0 ? "+" : ""}${formatNumber(value, 1)}%`;
}

function formatSignedSecondsDelta(value: number) {
  if (Math.abs(value) < 0.005) return "0 sec";
  return `${value > 0 ? "+" : "-"}${formatSecondsValue(Math.abs(value))}`;
}

function formatSignedInchesDelta(value: number) {
  if (Math.abs(value) < 0.05) return "0 in";
  return `${value > 0 ? "+" : "-"}${formatInchesValue(Math.abs(value))}`;
}

function workoutEntryChangeDisplay(
  current?: WorkoutEntry,
  baseline?: WorkoutEntry,
  station?: Pick<ActiveWorkoutStation, "measurementType" | "targetStyle" | "unit" | "performanceDirection">,
) {
  if (!current || !baseline || current.id === baseline.id || !workoutEntriesComparable(current, baseline)) return undefined;
  const measurementType = station?.measurementType;
  const direction = station?.performanceDirection ?? (current.unit === "sec" ? "LOWER_IS_BETTER" : "HIGHER_IS_BETTER");

  if (measurementType === "TIME" || current.unit === "sec") {
    if (typeof current.value !== "number" || typeof baseline.value !== "number") return undefined;
    const rawDelta = current.value - baseline.value;
    const improvementValue = direction === "LOWER_IS_BETTER" ? -rawDelta : rawDelta;
    return {
      label: formatSignedSecondsDelta(rawDelta),
      sortValue: improvementValue,
      className: weightRoomDeltaClass(improvementValue),
    };
  }

  if (measurementType === "DISTANCE" || measurementType === "HEIGHT" || current.unit === "in") {
    if (typeof current.value !== "number" || typeof baseline.value !== "number") return undefined;
    const rawDelta = current.value - baseline.value;
    const improvementValue = direction === "LOWER_IS_BETTER" ? -rawDelta : rawDelta;
    return {
      label: formatSignedInchesDelta(rawDelta),
      sortValue: improvementValue,
      className: weightRoomDeltaClass(improvementValue),
    };
  }

  if (measurementType === "WEIGHT_ONLY") {
    const currentWeight = current.weight ?? current.value;
    const baselineWeight = baseline.weight ?? baseline.value;
    if (typeof currentWeight !== "number" || typeof baselineWeight !== "number") return undefined;
    const rawDelta = currentWeight - baselineWeight;
    return {
      label: `${rawDelta > 0 ? "+" : ""}${formatNumber(rawDelta, 0)} lb`,
      sortValue: rawDelta,
      className: weightRoomDeltaClass(rawDelta),
    };
  }

  if (measurementType === "REPS_ONLY" || measurementType === "BODYWEIGHT_REPS" || measurementType === "COUNT") {
    const currentReps = current.reps ?? current.value;
    const baselineReps = baseline.reps ?? baseline.value;
    if (typeof currentReps !== "number" || typeof baselineReps !== "number") return undefined;
    const rawDelta = currentReps - baselineReps;
    return {
      label: `${rawDelta > 0 ? "+" : ""}${formatNumber(rawDelta, 0)} reps`,
      sortValue: rawDelta,
      className: weightRoomDeltaClass(rawDelta),
    };
  }

  const percent = workoutEntryPercentDelta(current, baseline);
  if (typeof percent !== "number") return undefined;
  return {
    label: formatWorkoutDelta(percent),
    sortValue: percent,
    className: weightRoomDeltaClass(percent),
  };
}

function weightRoomDeltaClass(value?: number) {
  if (typeof value !== "number" || Math.abs(value) < 0.05) return "";
  return value > 0 ? "positive" : "negative";
}

function workoutSessionTitle(data: AppData, session: WorkoutSession) {
  const lift = (data.scheduleEvents ?? []).find((event) => event.eventType === "Lift" && dateKeyFromIso(event.startAt) === session.date);
  return lift?.title ?? "Team Lift";
}

function trendForExercise(entries: WorkoutEntry[]) {
  const sorted = entries.slice().sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  const first = sorted[0];
  const latest = sorted[sorted.length - 1];
  const firstValue = first ? workoutEntryComparableForDisplay(first) : 0;
  const latestValue = latest ? workoutEntryComparableForDisplay(latest) : 0;
  const changePct = firstValue ? ((latestValue - firstValue) / Math.abs(firstValue)) * 100 : 0;
  return {
    exercise: latest?.exercise ?? first?.exercise ?? "Exercise",
    samples: sorted.length,
    changePct,
  };
}

function latestExerciseValue(data: AppData, playerId: ID, exercise: string): number | undefined {
  const entry = data.workoutEntries.find((item) => item.playerId === playerId && item.exercise === exercise);
  return entry?.weight ?? entry?.value;
}

function buildWeeklyWorkoutRow(data: AppData, player: Player) {
  const days = ["Mon", "Tue", "Thu", "Fri"].map((day) => {
    const session = data.workoutSessions.find((item) => item.playerId === player.id && item.weekOf === "2026-08-03" && item.day === day);
    return { day, completed: Boolean(session?.completed) };
  });
  return { player, days, completion: pct(days.filter((day) => day.completed).length, days.length) };
}

function practiceTotals(data: AppData, practiceId: ID) {
  const totals = deriveConcurrentPracticeTotals(data, practiceId);
  return {
    pitches: totals.pitches,
    swings: totals.swings,
    defense: totals.defense,
    liveBpPas: data.plateAppearances.filter((appearance) => appearance.practiceId === practiceId).length,
    hittingSessions: data.hittingSessions.filter((session) => session.practiceId === practiceId).length,
    pitchingSessions: data.pitchingSessions.filter((session) => session.practiceId === practiceId).length,
    defenseSessions: data.defenseSessions.filter((session) => session.practiceId === practiceId).length,
  };
}

function buildPracticeReviewSessions(data: AppData, practiceId: ID) {
  const playerById = new Map(data.players.map((player) => [player.id, player]));
  const hittingRows = data.hittingSessions
    .filter((session) => session.practiceId === practiceId)
    .map((session) => {
      const isLiveBp = session.type === "Live BP";
      const hitter = playerById.get(session.hitterId);
      const events = data.hittingEvents.filter((event) => event.sessionId === session.id);
      return {
        id: `hit-${session.id}`,
        category: (isLiveBp ? "Live BP" : "Hitting") as PracticeMetricsCategory,
        title: isLiveBp ? `${liveBpThrowerSourceLabel(session.liveBpThrowerSource ?? "PLAYER")} Live BP` : session.type,
        meta: hitter ? hitter.name : "Hitting session",
        count: `${events.length} swing${events.length === 1 ? "" : "s"}`,
      };
    });
  const pitchingRows = data.pitchingSessions
    .filter((session) => session.practiceId === practiceId)
    .map((session) => {
      const pitcher = playerById.get(session.pitcherId);
      const events = data.pitchEvents.filter((event) => event.sessionId === session.id);
      return {
        id: `pitch-${session.id}`,
        category: (session.type === "Live BP" ? "Live BP" : "Pitching") as PracticeMetricsCategory,
        title: session.type === "Live BP" ? `${liveBpThrowerSourceLabel(session.liveBpThrowerSource ?? "PLAYER")} Live BP` : session.type,
        meta: pitcher ? pitcher.name : "Pitching session",
        count: `${events.length} pitch${events.length === 1 ? "" : "es"}`,
      };
    });
  const defenseRows = data.defenseSessions
    .filter((session) => session.practiceId === practiceId)
    .map((session) => {
      const player = playerById.get(session.playerId);
      const events = data.defenseEvents.filter((event) => event.sessionId === session.id);
      return {
        id: `def-${session.id}`,
        category: "Defense" as PracticeMetricsCategory,
        title: session.station,
        meta: player ? player.name : "Defense session",
        count: `${events.length} rep${events.length === 1 ? "" : "s"}`,
      };
    });
  return [...hittingRows, ...pitchingRows, ...defenseRows];
}

function buildPracticeStandouts(data: AppData, practiceId: ID) {
  const players = data.players.filter((player) => !player.archived);
  const hitterRows = players.map((player) => {
    const stats = calculateHittingStats(data.hittingEvents.filter((event) => event.practiceId === practiceId && event.hitterId === player.id));
    return { player, stats };
  });
  const pitcherRows = players.map((player) => {
    const stats = calculatePitchingStats(data.pitchEvents.filter((event) => event.practiceId === practiceId && event.pitcherId === player.id));
    return { player, stats };
  });
  const defenderRows = players.map((player) => {
    const events = data.defenseEvents.filter((event) => event.practiceId === practiceId && event.playerId === player.id);
    return { player, events, clean: events.filter((event) => event.outcome !== "Error").length };
  });
  const hardHit = hitterRows.filter((row) => row.stats.totalSwings >= 8).sort((a, b) => b.stats.hardHitPct - a.stats.hardHitPct)[0];
  const impact = hitterRows.filter((row) => row.stats.totalSwings >= 8).sort((a, b) => b.stats.barrelPct - a.stats.barrelPct)[0];
  const maxExitVelocity = hitterRows.filter((row) => row.stats.maxExitVelocity !== undefined).sort((a, b) => (b.stats.maxExitVelocity ?? 0) - (a.stats.maxExitVelocity ?? 0))[0];
  const strike = pitcherRows.filter((row) => row.stats.totalPitches >= 12).sort((a, b) => b.stats.strikePct - a.stats.strikePct)[0];
  const command = pitcherRows.filter((row) => row.stats.totalPitches >= 12).sort((a, b) => b.stats.intendedTargetHitPct - a.stats.intendedTargetHitPct)[0];
  const defense = defenderRows.filter((row) => row.events.length >= 6).sort((a, b) => b.clean - a.clean)[0];

  return [
    hardHit && { label: "Top Hard-Hit %", player: hardHit.player, value: `${formatPct(hardHit.stats.hardHitPct)} / ${hardHit.stats.totalSwings} swings` },
    impact && { label: "Top Impact %", player: impact.player, value: `${formatPct(impact.stats.barrelPct)} / ${impact.stats.totalSwings} swings` },
    maxExitVelocity && { label: "Top EV", player: maxExitVelocity.player, value: `${formatNumber(maxExitVelocity.stats.maxExitVelocity, 1)} mph / ${maxExitVelocity.stats.exitVelocityRecorded} recorded` },
    strike && { label: "Best Strike %", player: strike.player, value: `${formatPct(strike.stats.strikePct)} / ${strike.stats.totalPitches} pitches` },
    command && command.stats.intendedTargetHitPct > 0 && { label: "Best Command %", player: command.player, value: `${formatPct(command.stats.intendedTargetHitPct)} target hit` },
    defense && { label: "Clean Defensive Reps", player: defense.player, value: `${defense.clean}/${defense.events.length} clean` },
  ].filter(Boolean) as Array<{ label: string; player: Player; value: string }>;
}

function isMachineHittingStation(station: HittingSession["type"]) {
  return station === "Machine" || station === "Hack Attack - FB" || station === "Hack Attack - CB";
}

function hittingStationUsesPitchType(station: HittingSession["type"]) {
  return isPracticeHittingPitchTypeAvailable(station);
}

function deriveHitDirectionFromFieldLocation(point: ZonePoint, bats?: Player["bats"]): Direction {
  if (point.x >= 0.42 && point.x <= 0.58) return "Middle";
  const leftSide = point.x < 0.42;
  if (bats === "L") return leftSide ? "Opposite" : "Pull";
  return leftSide ? "Pull" : "Opposite";
}

function normalizeHittingStation(station?: string): HittingSession["type"] {
  if (station === "Hack Attack - FB" || station === "Hack Attack - CB" || station === "Machine") return "Machine";
  if (station === "Tee" || station === "Front Toss" || station === "Coach BP" || station === "Live BP" || station === "Other") {
    return station;
  }
  return "Machine";
}

function practicePlayerStatus(data: AppData, practice: Practice | undefined, playerId: ID): PracticeAttendanceStatus {
  if (!practice) return "Present";
  return data.attendance.find((item) => item.practiceId === practice.id && item.playerId === playerId)?.status ?? "Present";
}

function availablePracticePlayers(data: AppData, practice: Practice | undefined) {
  const basePlayers = stablePracticeLineupPlayers(data, practice);
  if (!practice) return basePlayers;
  const participatingIds = new Set<ID>([
    ...practice.playerIds,
    ...practice.pitcherIds,
    ...practice.hitterIds,
    ...data.attendance.filter((item) => item.practiceId === practice.id).map((item) => item.playerId),
  ]);
  return basePlayers.filter((player) => {
    if (participatingIds.size && !participatingIds.has(player.id)) return false;
    const status = practicePlayerStatus(data, practice, player.id);
    return status === "Present" || status === "Late";
  });
}

function stablePracticeLineupPlayers(data: AppData, practice: Practice | undefined) {
  const activePlayers = data.players.filter((player) => !player.archived);
  const byId = new Map(activePlayers.map((player) => [player.id, player]));
  const orderedIds = practice ? [...practice.playerIds, ...practice.pitcherIds, ...practice.hitterIds] : [];
  const seen = new Set<ID>();
  const orderedPlayers = orderedIds
    .map((id) => byId.get(id))
    .filter((player): player is Player => {
      if (!player || seen.has(player.id)) return false;
      seen.add(player.id);
      return true;
    });
  const remaining = activePlayers
    .filter((player) => !seen.has(player.id))
    .sort(compareLineupPlayers);
  return [...orderedPlayers, ...remaining];
}

function compareLineupPlayers(a: Player, b: Player) {
  if (a.jerseyNumber !== b.jerseyNumber) return a.jerseyNumber - b.jerseyNumber;
  return a.name.localeCompare(b.name);
}

type PracticeMetricColumn = {
  key: PracticeMetricsSortKey;
  label: string;
  numeric?: boolean;
  render: (row: PracticeMetricRow) => React.ReactNode;
};

function defaultPracticeMetricSort(category: PracticeMetricsCategory): PracticeMetricsSortKey {
  if (category === "Pitching") return "pitches";
  if (category === "Defense") return "reps";
  if (category === "Live BP") return "liveBpPitches";
  return "swings";
}

function practiceMetricColumns(category: PracticeMetricsCategory): PracticeMetricColumn[] {
  const playerColumn: PracticeMetricColumn = {
    key: "player",
    label: "Player",
    render: (row) => (
      <span className="practice-metrics-player">
        <PlayerAvatar player={row.player} size="sm" compact />
        <span>
          <strong>{row.player.name}</strong>
          <small>{positionLine(row.player)}</small>
        </span>
      </span>
    ),
  };

  if (category === "Pitching") {
    return [
      playerColumn,
      { key: "pitches", label: "Pitches", numeric: true, render: (row) => row.pitches },
      { key: "strike", label: "Strike %", numeric: true, render: (row) => formatPct(row.strike, 0) },
      { key: "zone", label: "Zone %", numeric: true, render: (row) => formatPct(row.zone, 0) },
      { key: "avgVelo", label: "Avg Velo", numeric: true, render: (row) => formatOptionalMph(row.avgVelo) },
      { key: "maxVelo", label: "Max Velo", numeric: true, render: (row) => formatOptionalMph(row.maxVelo) },
    ];
  }

  if (category === "Defense") {
    return [
      playerColumn,
      { key: "positionWorked", label: "Pos", render: (row) => row.positionWorked },
      { key: "reps", label: "Reps", numeric: true, render: (row) => row.reps },
      { key: "cleanReps", label: "Clean", numeric: true, render: (row) => row.cleanReps },
      { key: "errors", label: "Errors", numeric: true, render: (row) => row.errors },
      { key: "clean", label: "Clean %", numeric: true, render: (row) => formatPct(row.clean, 0) },
      { key: "throwAcc", label: "Throw Acc.", numeric: true, render: (row) => row.throws ? formatPct(row.throwAcc, 0) : "--" },
    ];
  }

  if (category === "Live BP") {
    return [
      playerColumn,
      { key: "liveBpPitches", label: "Pitches", numeric: true, render: (row) => row.liveBpPitches },
      { key: "liveBpSwings", label: "Swings", numeric: true, render: (row) => row.liveBpSwings },
      { key: "liveBpPas", label: "PAs", numeric: true, render: (row) => row.liveBpPas },
      { key: "strike", label: "Strike %", numeric: true, render: (row) => formatPct(row.strike, 0) },
      { key: "avgEv", label: "Avg EV", numeric: true, render: (row) => formatOptionalMph(row.avgEv) },
    ];
  }

  return [
    playerColumn,
    { key: "swings", label: "Swings", numeric: true, render: (row) => row.swings },
    { key: "contact", label: "Contact", numeric: true, render: (row) => formatPct(row.contact, 0) },
    { key: "hard", label: "Hard %", numeric: true, render: (row) => formatPct(row.hard, 0) },
    { key: "avgEv", label: "Avg EV", numeric: true, render: (row) => formatOptionalMph(row.avgEv) },
    { key: "maxEv", label: "Max EV", numeric: true, render: (row) => formatOptionalMph(row.maxEv) },
  ];
}

function practiceHittingSessionOptions(data: AppData, practiceId?: ID) {
  if (!practiceId) return [];
  return data.hittingSessions
    .filter((session) => session.practiceId === practiceId && session.type !== "Live BP")
    .slice()
    .sort((left, right) => left.startedAt.localeCompare(right.startedAt));
}

function practicePitchingSessionOptions(data: AppData, practiceId?: ID) {
  if (!practiceId) return [];
  return data.pitchingSessions
    .filter((session) => session.practiceId === practiceId && session.type !== "Live BP")
    .slice()
    .sort((left, right) => left.startedAt.localeCompare(right.startedAt));
}

function hittingSessionAnalyticsLabel(session: HittingSession) {
  const pitchType = resolvePracticeHittingPitchType(session);
  const pitchMode = resolvePracticeHittingPitchMode(session.type, session);
  const pitch = pitchMode !== "OFF" && pitchType ? ` - ${PITCH_TYPE_LABELS[pitchType]}` : "";
  return `${normalizeHittingStation(session.type)}${pitch} · ${formatTime(session.startedAt)}`;
}

function buildPracticeMetricRows(data: AppData, category: PracticeMetricsCategory, practiceId?: ID, hittingSessionId?: ID, pitchingSessionId?: ID): PracticeMetricRow[] {
  const hittingSessionTypeById = new Map(data.hittingSessions.map((session) => [session.id, session.type]));
  const pitchingSessionTypeById = new Map(data.pitchingSessions.map((session) => [session.id, session.type]));
  return data.players
    .filter((player) => !player.archived)
    .map((player) => {
      const hittingEvents = data.hittingEvents.filter((event) => (
        event.hitterId === player.id
        && (!practiceId || event.practiceId === practiceId)
        && (!hittingSessionId || event.sessionId === hittingSessionId)
        && !event.isLiveBp
        && hittingSessionTypeById.get(event.sessionId) !== "Live BP"
      ));
      const hittingStats = calculateHittingStats(hittingEvents);
      const pitchEvents = data.pitchEvents.filter((event) => (
        event.pitcherId === player.id
        && (!practiceId || event.practiceId === practiceId)
        && (!pitchingSessionId || event.sessionId === pitchingSessionId)
        && pitchingSessionTypeById.get(event.sessionId) !== "Live BP"
      ));
      const pitchingStats = calculatePitchingStats(pitchEvents);
      const defenseEvents = data.defenseEvents.filter((event) => event.playerId === player.id && (!practiceId || event.practiceId === practiceId));
      const defenseStats = calculateDefenseStats(defenseEvents);
      const liveBpPitchEvents = data.pitchEvents.filter((event) => event.pitcherId === player.id && (!practiceId || event.practiceId === practiceId) && pitchingSessionTypeById.get(event.sessionId) === "Live BP");
      const liveBpHittingEvents = data.hittingEvents.filter((event) => (
        event.hitterId === player.id
        && (!practiceId || event.practiceId === practiceId)
        && (event.isLiveBp || hittingSessionTypeById.get(event.sessionId) === "Live BP" || Boolean(event.pitcherId))
      ));
      const liveBpPitchStats = calculatePitchingStats(liveBpPitchEvents);
      const liveBpHitStats = calculateHittingStats(liveBpHittingEvents);
      const liveBpPas = data.plateAppearances.filter((appearance) => (
        Boolean(appearance.practiceId)
        && (!practiceId || appearance.practiceId === practiceId)
        && (appearance.pitcherId === player.id || appearance.hitterId === player.id)
      )).length;
      const defenseSessionCount = data.defenseSessions.filter((session) => session.playerId === player.id && (!practiceId || session.practiceId === practiceId)).length;

      return {
        player,
        swings: hittingStats.totalSwings,
        contact: hittingStats.contactPct,
        hard: hittingStats.hardHitPct,
        avgEv: hittingStats.avgExitVelocity,
        maxEv: hittingStats.maxExitVelocity,
        pitches: pitchingStats.totalPitches,
        strike: category === "Live BP" ? liveBpPitchStats.strikePct : pitchingStats.strikePct,
        zone: pitchingStats.zonePct,
        avgVelo: pitchingStats.avgVelocity,
        maxVelo: pitchingStats.maxVelocity,
        positionWorked: mostCommonDefensePosition(defenseEvents, player),
        reps: defenseStats.totalReps,
        cleanReps: defenseStats.cleanReps,
        clean: defenseStats.cleanPct,
        errors: defenseStats.errors,
        greatPlays: defenseStats.greatPlays,
        throws: defenseStats.throwAttempts,
        accurateThrows: defenseStats.accurateThrows,
        throwAcc: defenseStats.throwAttempts ? defenseStats.throwAccuracyPct : undefined,
        defenseSessions: defenseSessionCount,
        liveBpPitches: liveBpPitchStats.totalPitches,
        liveBpSwings: liveBpHitStats.totalSwings,
        liveBpPas,
      };
    })
    .filter((row) => practiceMetricRowHasData(row, category));
}

function practiceMetricRowHasData(row: PracticeMetricRow, category: PracticeMetricsCategory) {
  if (category === "Pitching") return row.pitches > 0;
  if (category === "Defense") return row.reps > 0;
  if (category === "Live BP") return row.liveBpPitches > 0 || row.liveBpSwings > 0 || row.liveBpPas > 0;
  return row.swings > 0;
}

function sortPracticeMetricRows(rows: PracticeMetricRow[], sort: { key: PracticeMetricsSortKey; direction: SortDirection }) {
  const multiplier = sort.direction === "asc" ? 1 : -1;
  return rows.slice().sort((left, right) => {
    const leftValue = practiceMetricSortValue(left, sort.key);
    const rightValue = practiceMetricSortValue(right, sort.key);
    const result = typeof leftValue === "string" || typeof rightValue === "string"
      ? String(leftValue).localeCompare(String(rightValue), undefined, { numeric: true, sensitivity: "base" })
      : (leftValue ?? -1) - (rightValue ?? -1);
    return (result || left.player.jerseyNumber - right.player.jerseyNumber || left.player.name.localeCompare(right.player.name)) * multiplier;
  });
}

function practiceMetricSortValue(row: PracticeMetricRow, key: PracticeMetricsSortKey): string | number | undefined {
  if (key === "player") return row.player.name;
  return row[key];
}

function practiceMetricSummary(data: AppData, category: PracticeMetricsCategory, practiceId?: ID, hittingSessionId?: ID, pitchingSessionId?: ID) {
  if (category === "Pitching") {
    const sessionTypeById = new Map(data.pitchingSessions.map((session) => [session.id, session.type]));
    const events = data.pitchEvents.filter((event) => (
      (!practiceId || event.practiceId === practiceId)
      && (!pitchingSessionId || event.sessionId === pitchingSessionId)
      && sessionTypeById.get(event.sessionId) !== "Live BP"
    ));
    const stats = calculatePitchingStats(events);
    return [
      { label: "Pitches", value: stats.totalPitches },
      { label: "Strike", value: formatPct(stats.strikePct, 0) },
      { label: "Zone", value: formatPct(stats.zonePct, 0) },
      { label: "Avg Velo", value: formatOptionalMph(stats.avgVelocity) },
    ];
  }
  if (category === "Defense") {
    const events = data.defenseEvents.filter((event) => !practiceId || event.practiceId === practiceId);
    const stats = calculateDefenseStats(events);
    return [
      { label: "Reps", value: stats.totalReps },
      { label: "Clean", value: formatPct(stats.cleanPct, 0) },
      { label: "Errors", value: stats.errors },
      { label: "Throw Acc.", value: stats.throwAttempts ? formatPct(stats.throwAccuracyPct, 0) : "--" },
    ];
  }
  if (category === "Live BP") {
    const pitchingSessionTypeById = new Map(data.pitchingSessions.map((session) => [session.id, session.type]));
    const hittingSessionTypeById = new Map(data.hittingSessions.map((session) => [session.id, session.type]));
    const pitches = data.pitchEvents.filter((event) => (!practiceId || event.practiceId === practiceId) && pitchingSessionTypeById.get(event.sessionId) === "Live BP");
    const swings = data.hittingEvents.filter((event) => (!practiceId || event.practiceId === practiceId) && (event.isLiveBp || hittingSessionTypeById.get(event.sessionId) === "Live BP" || Boolean(event.pitcherId)));
    const pitching = calculatePitchingStats(pitches);
    const hitting = calculateHittingStats(swings);
    return [
      { label: "Pitches", value: pitching.totalPitches },
      { label: "Swings", value: hitting.totalSwings },
      { label: "PAs", value: data.plateAppearances.filter((appearance) => appearance.practiceId && (!practiceId || appearance.practiceId === practiceId)).length },
      { label: "Avg EV", value: formatOptionalMph(hitting.avgExitVelocity) },
    ];
  }
  const sessionTypeById = new Map(data.hittingSessions.map((session) => [session.id, session.type]));
  const events = data.hittingEvents.filter((event) => (
    (!practiceId || event.practiceId === practiceId)
    && (!hittingSessionId || event.sessionId === hittingSessionId)
    && !event.isLiveBp
    && sessionTypeById.get(event.sessionId) !== "Live BP"
  ));
  const stats = calculateHittingStats(events);
  return [
    { label: "Swings", value: stats.totalSwings },
    { label: "Contact", value: formatPct(stats.contactPct, 0) },
    { label: "Hard", value: formatPct(stats.hardHitPct, 0) },
    { label: "Avg EV", value: formatOptionalMph(stats.avgExitVelocity) },
  ];
}

function formatOptionalMph(value?: number) {
  return typeof value === "number" && Number.isFinite(value) ? `${formatNumber(value, 1)} mph` : "--";
}

function liveBpThrowerSourceLabel(source: LiveBpThrowerSource) {
  return LIVE_BP_THROWER_LABELS[source] ?? "Player";
}

function isPracticeSessionReusable(session: { status?: string }) {
  return (session.status ?? "ACTIVE") !== "CANCELLED";
}

function isPracticeSessionLive(data: AppData, sessionId: ID, nowMs = Date.now()) {
  const lastActivityAt = practiceSessionLastActivityAt(data, sessionId);
  return Boolean(lastActivityAt && nowMs - Date.parse(lastActivityAt) <= PRACTICE_ACTIVE_SESSION_GRACE_MS);
}

function practiceSessionLastActivityAt(data: AppData, sessionId: ID) {
  const timestamps = [
    ...data.practiceSessionContributors.filter((row) => row.sessionId === sessionId).map((row) => row.lastActiveAt),
    ...data.hittingEvents.filter((event) => event.sessionId === sessionId).map((event) => event.createdAt),
    ...data.pitchEvents.filter((event) => event.sessionId === sessionId).map((event) => event.createdAt),
    ...data.defenseEvents.filter((event) => event.sessionId === sessionId).map((event) => event.createdAt),
  ].filter(Boolean) as string[];
  return timestamps.sort((left, right) => right.localeCompare(left))[0];
}

function practiceSessionActivityLabel(lastActiveAt: string, nowMs: number) {
  const ageMs = Math.max(0, nowMs - Date.parse(lastActiveAt));
  if (ageMs < PRACTICE_SESSION_HEARTBEAT_MS + 15 * 1000) return "Live now";
  if (ageMs < PRACTICE_ACTIVE_SESSION_GRACE_MS) return "Recently active";
  const minutes = Math.max(1, Math.round(ageMs / 60000));
  return `${minutes}m ago`;
}

function buildActivePracticeSessions(data: AppData, practiceId: ID, nowMs = Date.now()): PracticeActiveSessionRow[] {
  const playerById = new Map(data.players.map((player) => [player.id, player]));
  const currentProfileId = data.teamContext?.profile?.id;
  const rows: PracticeActiveSessionRow[] = [
    ...data.hittingSessions
      .filter((session) => session.type !== "Live BP" && session.practiceId === practiceId && isPracticeSessionReusable(session) && isPracticeSessionLive(data, session.id, nowMs))
      .map((session) => {
        const player = playerById.get(session.hitterId);
        const events = data.hittingEvents.filter((event) => event.sessionId === session.id);
        const lastActiveAt = practiceSessionLastActivityAt(data, session.id) ?? session.updatedAt ?? session.startedAt;
        return {
          id: `hit-${session.id}`,
          mode: "Hitting" as const,
          sessionId: session.id,
          title: session.title ?? `${session.type} Hitting`,
          station: session.type,
          primaryPlayerId: session.hitterId,
          playerLine: player?.name ?? "Hitter",
          count: `${events.filter((event) => event.action !== "Took pitch").length} swings`,
          contributors: contributorLabels(data, session.id, session.createdByProfileId, session.contributorProfileIds),
          isMine: Boolean(currentProfileId && (session.createdByProfileId === currentProfileId || session.contributorProfileIds?.includes(currentProfileId))),
          startedAt: session.startedAt,
          lastActiveAt,
          activityLabel: practiceSessionActivityLabel(lastActiveAt, nowMs),
        };
      }),
    ...data.hittingSessions
      .filter((session) => session.type === "Live BP" && (session.liveBpThrowerSource ?? "PLAYER") !== "PLAYER" && session.practiceId === practiceId && isPracticeSessionReusable(session) && isPracticeSessionLive(data, session.id, nowMs))
      .map((session) => {
        const hitter = playerById.get(session.hitterId);
        const events = data.hittingEvents.filter((event) => event.sessionId === session.id);
        const lastActiveAt = practiceSessionLastActivityAt(data, session.id) ?? session.updatedAt ?? session.startedAt;
        const throwerSource = session.liveBpThrowerSource ?? "COACH";
        return {
          id: `live-hit-${session.id}`,
          mode: "Live BP" as const,
          sessionId: session.id,
          title: `${liveBpThrowerSourceLabel(throwerSource)} Live BP`,
          station: session.station ?? "Live BP",
          throwerSource,
          primaryPlayerId: session.hitterId,
          secondaryPlayerId: session.hitterId,
          playerLine: `${hitter?.name ?? "Hitter"} · ${liveBpThrowerSourceLabel(throwerSource)} throwing`,
          count: `${events.length} pitches`,
          contributors: contributorLabels(data, session.id, session.createdByProfileId, session.contributorProfileIds),
          isMine: Boolean(currentProfileId && (session.createdByProfileId === currentProfileId || session.contributorProfileIds?.includes(currentProfileId))),
          startedAt: session.startedAt,
          lastActiveAt,
          activityLabel: practiceSessionActivityLabel(lastActiveAt, nowMs),
        };
      }),
    ...data.pitchingSessions
      .filter((session) => session.practiceId === practiceId && isPracticeSessionReusable(session) && isPracticeSessionLive(data, session.id, nowMs))
      .map((session) => {
        const player = playerById.get(session.pitcherId);
        const hitter = session.hitterId ? playerById.get(session.hitterId) : undefined;
        const events = data.pitchEvents.filter((event) => event.sessionId === session.id);
        const lastActiveAt = practiceSessionLastActivityAt(data, session.id) ?? session.updatedAt ?? session.startedAt;
        return {
          id: `pitch-${session.id}`,
          mode: session.type === "Live BP" ? "Live BP" as const : "Pitching" as const,
          sessionId: session.id,
          title: session.title ?? (session.type === "Live BP" ? `${liveBpThrowerSourceLabel(session.liveBpThrowerSource ?? "PLAYER")} Live BP` : `${session.type} Pitching`),
          station: session.station ?? session.type,
          throwerSource: session.type === "Live BP" ? session.liveBpThrowerSource ?? "PLAYER" : undefined,
          primaryPlayerId: session.pitcherId,
          secondaryPlayerId: session.hitterId,
          playerLine: hitter ? `${player?.name ?? "Pitcher"} vs ${hitter.name}` : player?.name ?? "Pitcher",
          count: `${events.length} pitches`,
          contributors: contributorLabels(data, session.id, session.createdByProfileId, session.contributorProfileIds),
          isMine: Boolean(currentProfileId && (session.createdByProfileId === currentProfileId || session.contributorProfileIds?.includes(currentProfileId))),
          startedAt: session.startedAt,
          lastActiveAt,
          activityLabel: practiceSessionActivityLabel(lastActiveAt, nowMs),
        };
      }),
    ...data.defenseSessions
      .filter((session) => session.practiceId === practiceId && isPracticeSessionReusable(session) && isPracticeSessionLive(data, session.id, nowMs))
      .map((session) => {
        const player = playerById.get(session.playerId);
        const events = data.defenseEvents.filter((event) => event.sessionId === session.id);
        const lastActiveAt = practiceSessionLastActivityAt(data, session.id) ?? session.updatedAt ?? session.startedAt;
        return {
          id: `def-${session.id}`,
          mode: "Defense" as const,
          sessionId: session.id,
          title: session.drillContext ?? session.title ?? `${session.station} Defense`,
          station: session.station,
          primaryPlayerId: session.playerId,
          playerLine: [player?.name ?? "Defender", session.positionWorked].filter(Boolean).join(" · "),
          count: `${events.length} reps`,
          contributors: contributorLabels(data, session.id, session.createdByProfileId, session.contributorProfileIds),
          isMine: Boolean(currentProfileId && (session.createdByProfileId === currentProfileId || session.contributorProfileIds?.includes(currentProfileId))),
          startedAt: session.startedAt,
          lastActiveAt,
          activityLabel: practiceSessionActivityLabel(lastActiveAt, nowMs),
        };
      }),
  ];
  return rows.sort((a, b) => Number(b.isMine) - Number(a.isMine) || b.lastActiveAt.localeCompare(a.lastActiveAt) || b.startedAt.localeCompare(a.startedAt));
}

function contributorLabels(data: AppData, sessionId: ID, createdByProfileId?: ID, contributorProfileIds?: ID[]) {
  const profile = data.teamContext?.profile;
  const staffByProfileId = new Map((data.staffMembers ?? []).filter((member) => member.profileId).map((member) => [member.profileId as ID, member.displayName]));
  const ids = new Set<ID>([
    ...(createdByProfileId ? [createdByProfileId] : []),
    ...(contributorProfileIds ?? []),
    ...((data.practiceSessionContributors ?? []).filter((row) => row.sessionId === sessionId).map((row) => row.profileId)),
  ]);
  return [...ids].map((profileId) => {
    if (profileId === profile?.id) return profileDisplayName(data.teamContext);
    return staffByProfileId.get(profileId) ?? "Coach";
  });
}

function buildPlayerRecentActivity(data: AppData, player: Player) {
  const practicesById = new Map(data.practices.map((practice) => [practice.id, practice]));
  const activities = [
    ...data.hittingSessions
      .filter((session) => session.hitterId === player.id)
      .map((session) => {
        const practice = practicesById.get(session.practiceId);
        const stats = calculateHittingStats(data.hittingEvents.filter((event) => event.sessionId === session.id));
        return {
          key: `hit-${session.id}`,
          date: practice?.date ?? session.startedAt,
          type: "Hitting",
          title: `${session.type} hitting`,
          meta: `${shortDate(practice?.date ?? session.startedAt.slice(0, 10))} - ${stats.totalSwings} swings - ${formatPct(stats.hardHitPct)} hard hit`,
          summaryType: "Hitting" as const,
          sessionId: session.id,
        };
      }),
    ...data.pitchingSessions
      .filter((session) => session.pitcherId === player.id)
      .map((session) => {
        const practice = practicesById.get(session.practiceId);
        const stats = calculatePitchingStats(data.pitchEvents.filter((event) => event.sessionId === session.id));
        return {
          key: `pitch-${session.id}`,
          date: practice?.date ?? session.startedAt,
          type: "Pitching",
          title: `${session.type} session`,
          meta: `${shortDate(practice?.date ?? session.startedAt.slice(0, 10))} - ${stats.totalPitches} pitches - ${formatPct(stats.strikePct)} strikes`,
          summaryType: "Pitching" as const,
          sessionId: session.id,
        };
      }),
    ...data.defenseSessions
      .filter((session) => session.playerId === player.id)
      .map((session) => {
        const practice = practicesById.get(session.practiceId);
        const reps = data.defenseEvents.filter((event) => event.sessionId === session.id);
        const stats = calculateDefenseStats(reps);
        return {
          key: `def-${session.id}`,
          date: practice?.date ?? session.startedAt,
          type: "Defense",
          title: session.drillContext ?? session.station,
          meta: `${shortDate(practice?.date ?? session.startedAt.slice(0, 10))} - ${stats.totalReps} reps - ${formatPct(stats.cleanPct)} clean`,
          summaryType: "Defense" as const,
          sessionId: session.id,
        };
      }),
    ...data.workoutSessions
      .filter((session) => session.playerId === player.id)
      .map((session) => ({
        key: `weight-${session.id}`,
        date: session.date,
        type: "Weight Room",
        title: `${session.day} lift`,
        meta: `${shortDate(session.date)} - ${session.completed ? "completed" : "in progress"}`,
        summaryType: undefined,
        sessionId: undefined,
      })),
    ...data.games
      .filter((game) => game.lineup.includes(player.id) || game.currentPitcherId === player.id || game.currentBatterId === player.id || game.startingPitcherId === player.id)
      .map((game) => ({
        key: `game-${game.id}`,
        date: game.date,
        type: "Game",
        title: `vs ${game.opponent}`,
        meta: `${shortDate(game.date)} - ${game.result ?? "not final"} ${game.metrolinaScore}-${game.opponentScore}`,
        summaryType: undefined,
        sessionId: undefined,
      })),
  ];

  return activities.sort((a, b) => b.date.localeCompare(a.date));
}

function buildPlayerMembershipCards(data: AppData, player: Player) {
  const teamById = new Map((data.teamContext?.availableTeams ?? []).map((team) => [team.teamId, team]));
  const memberships = (data.playerTeamMemberships ?? []).filter((membership) => membership.playerId === player.id);

  if (!memberships.length && data.teamContext?.currentTeam) {
    const team = data.teamContext.currentTeam;
    return [{
      key: `${team.teamId}-${team.seasonId ?? "season"}`,
      team: team.teamName,
      season: team.seasonName ?? data.settings.rosterSeason,
      status: player.rosterStatus ?? "Undecided",
      number: player.jerseyNumber,
    }];
  }

  return memberships
    .filter((membership) => membership.active)
    .map((membership) => {
      const team = teamById.get(membership.teamId);
      return {
        key: membership.id,
        team: team?.teamName ?? "Team membership",
        season: team?.seasonName ?? data.settings.rosterSeason,
        status: membership.rosterStatus,
        number: membership.jerseyNumber ?? player.jerseyNumber,
      };
    });
}

function buildPlayerGameSnapshot(data: AppData, player: Player) {
  const games = data.games.filter(
    (game) => game.lineup.includes(player.id) || game.currentPitcherId === player.id || game.currentBatterId === player.id || game.startingPitcherId === player.id,
  );
  const events = data.gameEvents.filter((event) => event.batterId === player.id);
  const hitOutcomes: GameBallInPlayOutcome[] = ["Single", "Double", "Triple", "Home Run"];
  const atBatOutcomes: GameBallInPlayOutcome[] = ["Single", "Double", "Triple", "Home Run", "Ground Out", "Fly Out", "Line Out", "Pop Out", "Error", "Fielder's Choice"];
  const hits = events.filter((event) => event.ballInPlayOutcome && hitOutcomes.includes(event.ballInPlayOutcome)).length;
  const atBats = events.filter((event) => event.ballInPlayOutcome && atBatOutcomes.includes(event.ballInPlayOutcome)).length;

  return {
    games: games.length,
    hits,
    atBats,
    avg: atBats ? hits / atBats : 0,
  };
}

function buildSessionSummary(data: AppData, summary: { type: "Hitting" | "Pitching" | "Defense"; sessionId: ID }) {
  if (summary.type === "Hitting") {
    const session = data.hittingSessions.find((item) => item.id === summary.sessionId);
    const player = data.players.find((item) => item.id === session?.hitterId);
    const stats = calculateHittingStats(data.hittingEvents.filter((event) => event.sessionId === summary.sessionId));
    return {
      title: `${player?.name ?? "Hitter"} - ${session?.type ?? "Hitting"}`,
      stats: [
        { label: "Swings", value: stats.totalSwings },
        { label: "Contact", value: formatPct(stats.contactPct) },
        { label: "Hard Hit", value: formatPct(stats.hardHitPct) },
        { label: "Impact", value: formatPct(stats.barrelPct) },
        { label: "Line Drive", value: formatPct(stats.lineDrivePct) },
        ...(stats.exitVelocityRecorded > 0 ? [{ label: "Avg EV", value: `${formatNumber(stats.avgExitVelocity, 1)} mph`, sub: `${stats.exitVelocityRecorded} recorded` }] : []),
        ...(stats.maxExitVelocity !== undefined ? [{ label: "Max EV", value: `${formatNumber(stats.maxExitVelocity, 1)} mph` }] : []),
      ],
    };
  }
  if (summary.type === "Pitching") {
    const session = data.pitchingSessions.find((item) => item.id === summary.sessionId);
    const player = data.players.find((item) => item.id === session?.pitcherId);
    const events = data.pitchEvents.filter((event) => event.sessionId === summary.sessionId);
    const stats = calculatePitchingStats(events);
    const mix = Object.values(stats.byPitchType)
      .sort((a, b) => b.pitches - a.pitches)
      .slice(0, 3)
      .map((item) => `${PITCH_TYPE_LABELS[item.pitchType]} ${item.pitches}`)
      .join(" / ");
    return {
      title: `${player?.name ?? "Pitcher"} - ${session?.type ?? "Pitching"}`,
      stats: [
        { label: "Pitches", value: stats.totalPitches },
        { label: "Strike %", value: formatPct(stats.strikePct) },
        { label: "Zone %", value: formatPct(stats.zonePct) },
        { label: "Avg Velo", value: formatOptionalMph(stats.avgVelocity) },
        { label: "Max Velo", value: formatOptionalMph(stats.maxVelocity), sub: mix || `${events.length} tracked` },
      ],
    };
  }
  const session = data.defenseSessions.find((item) => item.id === summary.sessionId);
  const player = data.players.find((item) => item.id === session?.playerId);
  const events = data.defenseEvents.filter((event) => event.sessionId === summary.sessionId);
  const stats = calculateDefenseStats(events);
  const repTypes = Object.values(stats.byRepType)
    .sort((left, right) => right.reps - left.reps)
    .slice(0, 3)
    .map((item) => `${item.label} ${item.reps}`)
    .join(" / ");
  return {
    title: `${player?.name ?? "Defender"} - ${session?.drillContext ?? session?.station ?? "Defense"}`,
    stats: [
      { label: "Reps", value: stats.totalReps },
      { label: "Clean", value: stats.cleanReps },
      { label: "Clean %", value: formatPct(stats.cleanPct) },
      { label: "Errors", value: stats.errors },
      { label: "Throw Acc.", value: stats.throwAttempts ? formatPct(stats.throwAccuracyPct) : "--", sub: repTypes || undefined },
    ],
  };
}

type EnsureHittingSessionOptions = {
  pitchTrackingMode?: HittingPitchTrackingMode;
  defaultPitchType?: PitchType;
  machineVelocity?: number;
};

function ensureHittingSession(
  data: AppData,
  practice: Practice,
  playerId: ID,
  type: HittingSession["type"],
  profileId?: ID,
  liveBpThrowerSource: LiveBpThrowerSource = "PLAYER",
  options: EnsureHittingSessionOptions = {},
) {
  const now = new Date().toISOString();
  const existing = data.hittingSessions.find((session) => (
    session.practiceId === practice.id
    && session.hitterId === playerId
    && isPracticeSessionReusable(session)
    && (session.type === type || (type === "Machine" && isMachineHittingStation(session.type)))
    && (type !== "Live BP" || (session.liveBpThrowerSource ?? "PLAYER") === liveBpThrowerSource)
  ));
  if (existing) {
    const nextPitchMode = type === "Live BP"
      ? existing.pitchTrackingMode
      : options.pitchTrackingMode ?? existing.pitchTrackingMode ?? defaultPracticeHittingPitchMode(type);
    const nextDefaultPitchType = type === "Live BP" || nextPitchMode === "OFF"
      ? undefined
      : options.defaultPitchType ?? existing.defaultPitchType ?? existing.machinePitchType;
    const session = {
      ...existing,
      pitchTrackingMode: nextPitchMode,
      defaultPitchType: nextDefaultPitchType,
      machinePitchType: nextPitchMode === "OFF" ? undefined : nextDefaultPitchType ?? existing.machinePitchType,
      machineVelocity: options.machineVelocity ?? existing.machineVelocity,
      contributorProfileIds: withContributorProfile(existing.contributorProfileIds, profileId),
      updatedAt: now,
    };
    const nextData = {
      ...data,
      hittingSessions: data.hittingSessions.map((item) => (item.id === session.id ? session : item)),
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    };
    return { data: nextData, session };
  }
  const pitchTrackingMode = type === "Live BP" ? undefined : options.pitchTrackingMode ?? defaultPracticeHittingPitchMode(type);
  const defaultPitchType = type !== "Live BP" && pitchTrackingMode !== "OFF"
    ? options.defaultPitchType ?? (type === "Hack Attack - CB" ? "Curveball" : "4-Seam")
    : undefined;
  const session: HittingSession = {
    id: createId("hs"),
    practiceId: practice.id,
    hitterId: playerId,
    type,
    liveBpThrowerSource: type === "Live BP" ? liveBpThrowerSource : undefined,
    roundGoals: ["Line drives"],
    plannedReps: 20,
    machineVelocity: isMachineHittingStation(type) ? options.machineVelocity ?? 85 : undefined,
    machinePitchType: defaultPitchType,
    pitchTrackingMode,
    defaultPitchType,
    startedAt: now,
    title: type === "Live BP" ? `${liveBpThrowerSourceLabel(liveBpThrowerSource)} Live BP` : `${type} - Hitting`,
    status: "ACTIVE",
    createdByProfileId: profileId,
    contributorProfileIds: withContributorProfile([], profileId),
    location: practice.location,
    station: type === "Live BP" ? liveBpThrowerSourceLabel(liveBpThrowerSource) : type,
    entryPolicy: "COACH_ONLY",
    updatedAt: now,
  };
  return {
    data: {
      ...data,
      hittingSessions: [session, ...data.hittingSessions],
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    },
    session,
  };
}

function ensurePitchingSession(data: AppData, practice: Practice, playerId: ID, type: PitchingSession["type"], profileId?: ID, hitterId?: ID, liveBpThrowerSource: LiveBpThrowerSource = "PLAYER") {
  const now = new Date().toISOString();
  const existing = data.pitchingSessions.find((session) => (
    session.practiceId === practice.id
    && session.pitcherId === playerId
    && session.type === type
    && isPracticeSessionReusable(session)
    && (type !== "Live BP" || (session.liveBpThrowerSource ?? "PLAYER") === liveBpThrowerSource)
  ));
  if (existing) {
    const session = {
      ...existing,
      hitterId: hitterId ?? existing.hitterId,
      contributorProfileIds: withContributorProfile(existing.contributorProfileIds, profileId),
      updatedAt: now,
    };
    const nextData = {
      ...data,
      pitchingSessions: data.pitchingSessions.map((item) => (item.id === session.id ? session : item)),
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    };
    return { data: nextData, session };
  }
  const session: PitchingSession = {
    id: createId("ps"),
    practiceId: practice.id,
    pitcherId: playerId,
    type,
    liveBpThrowerSource: type === "Live BP" ? liveBpThrowerSource : undefined,
    hitterId,
    focusTags: ["Strike throwing"],
    intendedFocus: "Win the zone early and finish every pitch.",
    startedAt: now,
    title: type === "Live BP" ? `${liveBpThrowerSourceLabel(liveBpThrowerSource)} Live BP` : `${type} - Pitching`,
    status: "ACTIVE",
    createdByProfileId: profileId,
    contributorProfileIds: withContributorProfile([], profileId),
    location: practice.location,
    station: type === "Live BP" ? liveBpThrowerSourceLabel(liveBpThrowerSource) : "Bullpen",
    entryPolicy: "COACH_ONLY",
    updatedAt: now,
  };
  return {
    data: {
      ...data,
      pitchingSessions: [session, ...data.pitchingSessions],
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    },
    session,
  };
}

function defenseDrillOption(value: DefenseDrillContext): DefenseDrillOption {
  return DEFENSE_DRILLS.find((drill) => drill.value === value) ?? DEFENSE_DRILLS[0];
}

function defaultDefenseDrillForStation(station: DefenseStation): DefenseDrillContext {
  return DEFENSE_DRILLS.find((drill) => drill.station === station)?.value ?? "Team Defense";
}

function defenseStationForDrill(drill: DefenseDrillContext): DefenseStation {
  return defenseDrillOption(drill).station;
}

function defensePositionOptions(drill: DefenseDrillContext): Position[] {
  return defenseDrillOption(drill).positions;
}

function defaultDefensePositionForPlayer(player: Player, drill: DefenseDrillContext): Position {
  const options = defensePositionOptions(drill);
  if (options.includes(player.primaryPosition)) return player.primaryPosition;
  if (player.secondaryPosition && options.includes(player.secondaryPosition)) return player.secondaryPosition;
  if ((player.primaryPosition === "RHP" || player.primaryPosition === "LHP") && options.includes("P")) return "P";
  return defenseDrillOption(drill).defaultPosition;
}

function defenseSubtypeOptions(repType: DefenseRepType, position?: Position): DefenseRepSubtype[] {
  if (repType === "Ground Ball") return ["Routine", "Forehand", "Backhand", "Slow Roller", "Charge"];
  if (repType === "Fly Ball") return ["Routine", "Drop Step", "Over Shoulder"];
  if (repType === "Line Drive") return ["Routine", "Forehand", "Backhand"];
  if (repType === "Double Play") return ["Routine", "Forehand", "Backhand"];
  if (repType === "Throw") return position === "C" ? ["Throwdown", "Other"] : ["Cutoff", "Relay", "Routine"];
  if (repType === "Block") return ["Block"];
  if (repType === "Pick") return ["Pick"];
  if (repType === "Bunt") return ["Bunt"];
  return ["Other"];
}

function defenseDrillThrowRelevant(drill: DefenseDrillContext, repType: DefenseRepType) {
  if (repType === "Block" || repType === "Pick") return false;
  return defenseDrillOption(drill).throwRelevant || repType === "Throw" || repType === "Double Play" || repType === "Bunt";
}

function createDefenseLogDraft(player: Player, drill: DefenseDrillContext, position: Position, seed?: Partial<DefenseLogDraft>): DefenseLogDraft {
  const option = defenseDrillOption(drill);
  const repType = option.repTypeLocked ? option.defaultRepType : seed?.repType ?? option.defaultRepType;
  const subtypeOptions = defenseSubtypeOptions(repType, position);
  const repSubtype = option.subtypeLocked
    ? option.defaultRepSubtype
    : seed?.repSubtype && subtypeOptions.includes(seed.repSubtype)
      ? seed.repSubtype
      : option.defaultRepSubtype ?? subtypeOptions[0];
  return {
    positionWorked: position,
    drillContext: drill,
    repType,
    repSubtype,
    result: seed?.result ?? "Clean",
    throwResult: defenseDrillThrowRelevant(drill, repType) ? seed?.throwResult ?? "Accurate" : undefined,
    difficulty: seed?.difficulty,
    location: seed?.location,
    coachNote: seed?.coachNote,
  };
}

function defenseDraftFromEvent(event: DefenseEvent, player: Player, fallbackDrill: DefenseDrillContext, fallbackPosition: Position): DefenseLogDraft {
  const drill = event.drillContext ?? fallbackDrill;
  const position = event.positionWorked ?? fallbackPosition ?? defaultDefensePositionForPlayer(player, drill);
  return createDefenseLogDraft(player, drill, position, {
    repType: defenseEventRepType(event),
    repSubtype: event.repSubtype,
    result: defenseEventResult(event),
    throwResult: defenseEventThrowResult(event),
    difficulty: event.difficulty,
    location: event.location,
    coachNote: event.coachNote,
  });
}

function normalizeDefenseDraft(draft: DefenseLogDraft, trackLocation: boolean, trackDifficulty: boolean): DefenseLogDraft {
  const repType = defenseDrillOption(draft.drillContext).repTypeLocked ? defenseDrillOption(draft.drillContext).defaultRepType : draft.repType;
  const subtype = defenseDrillOption(draft.drillContext).subtypeLocked
    ? defenseDrillOption(draft.drillContext).defaultRepSubtype
    : draft.repSubtype;
  const throwResult = defenseDrillThrowRelevant(draft.drillContext, repType) ? draft.throwResult ?? "Accurate" : undefined;
  return {
    ...draft,
    repType,
    repSubtype: subtype,
    throwResult,
    difficulty: trackDifficulty ? draft.difficulty : undefined,
    location: trackLocation ? draft.location : undefined,
  };
}

function defenseResultTone(result: DefenseOutcome) {
  if (result === "Error" || result === "Missed Rep") return "negative";
  if (result === "Great Play" || result === "Good Play" || result === "Clean") return "positive";
  return "";
}

function defenseEventTone(event: DefenseEvent) {
  return isDefenseErrorEvent(event) ? "negative" : "positive";
}

function throwQualityForDefenseDraft(draft: DefenseLogDraft) {
  if (draft.throwResult === "Inaccurate") return "Poor";
  if (draft.result === "Great Play") return "Plus";
  if (draft.throwResult === "Accurate" || draft.result === "Clean" || draft.result === "Good Play") return "Good";
  return "Average";
}

function defenseRangeForDraft(draft: DefenseLogDraft) {
  if (draft.difficulty) return draft.difficulty;
  if (draft.result === "Great Play") return "Plus";
  if (draft.result === "Good Play") return "Difficult";
  return "Routine";
}

function defenseErrorTypeForDraft(draft: DefenseLogDraft): DefenseEvent["errorType"] {
  if (draft.throwResult === "Inaccurate") return "Throwing";
  if (draft.repType === "Throw" || draft.repType === "Double Play") return "Throwing";
  return "Fielding";
}

function defenseSessionAnalyticsLabel(session: DefenseSession) {
  const drill = session.drillContext ?? defaultDefenseDrillForStation(session.station);
  return [session.positionWorked, drill, formatTime(session.startedAt)].filter(Boolean).join(" - ");
}

function mostCommonDefensePosition(events: DefenseEvent[], player: Player) {
  const counts = new Map<string, number>();
  events.forEach((event) => {
    const position = defenseEventPosition(event, player.primaryPosition);
    counts.set(position, (counts.get(position) ?? 0) + 1);
  });
  return [...counts.entries()].sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))[0]?.[0] ?? player.primaryPosition;
}

function ensureDefenseSession(
  data: AppData,
  practice: Practice,
  playerId: ID,
  station: DefenseStation,
  profileId?: ID,
  options?: { drillContext?: DefenseDrillContext; positionWorked?: Position },
) {
  const now = new Date().toISOString();
  const drillContext = options?.drillContext ?? defaultDefenseDrillForStation(station);
  const positionWorked = options?.positionWorked;
  const existing = data.defenseSessions.find((session) => (
    session.practiceId === practice.id
    && session.playerId === playerId
    && session.station === station
    && (session.drillContext ?? defaultDefenseDrillForStation(session.station)) === drillContext
    && (positionWorked ? session.positionWorked === positionWorked : true)
    && isPracticeSessionReusable(session)
  ));
  if (existing) {
    const session = {
      ...existing,
      drillContext: existing.drillContext ?? drillContext,
      positionWorked: existing.positionWorked ?? positionWorked,
      contributorProfileIds: withContributorProfile(existing.contributorProfileIds, profileId),
      updatedAt: now,
    };
    const nextData = {
      ...data,
      defenseSessions: data.defenseSessions.map((item) => (item.id === session.id ? session : item)),
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    };
    return { data: nextData, session };
  }
  const session = {
    id: createId("ds"),
    practiceId: practice.id,
    playerId,
    station,
    drillContext,
    positionWorked,
    mode: "Quick Practice" as const,
    startedAt: now,
    title: `${drillContext} - Defense`,
    status: "ACTIVE" as const,
    createdByProfileId: profileId,
    contributorProfileIds: withContributorProfile([], profileId),
    location: practice.location,
    entryPolicy: "COACH_ONLY" as const,
    updatedAt: now,
  };
  return {
    data: {
      ...data,
      defenseSessions: [session, ...data.defenseSessions],
      practiceSessionContributors: touchSessionContributor(data.practiceSessionContributors ?? [], { sessionId: session.id, profileId, at: now }),
    },
    session,
  };
}

function withContributorProfile(ids: ID[] | undefined, profileId?: ID) {
  if (!profileId) return ids ?? [];
  return [...new Set([...(ids ?? []), profileId])];
}

function applyGameOutcome(game: Game, outcome: GamePitchOutcome, ballInPlayOutcome?: GameBallInPlayOutcome): Game {
  let balls = game.balls;
  let strikes = game.strikes;
  let outs = game.outs;
  let metrolinaScore = game.metrolinaScore;
  let opponentScore = game.opponentScore;
  let runners = { ...game.runners };

  if (outcome === "Ball") balls += 1;
  if (outcome === "Called Strike" || outcome === "Swinging Strike") strikes += 1;
  if (outcome === "Foul" && strikes < 2) strikes += 1;

  const isStrikeout = strikes >= 3;
  const isWalk = balls >= 4;
  const isOut = ballInPlayOutcome && ["Ground Out", "Fly Out", "Line Out", "Pop Out", "Sac Fly", "Sac Bunt"].includes(ballInPlayOutcome);
  const isHit = ballInPlayOutcome && ["Single", "Double", "Triple", "Home Run", "Error"].includes(ballInPlayOutcome);

  if (isStrikeout || isOut) outs += 1;
  if (isWalk) runners.first = game.currentBatterId;
  if (isHit) {
    const runnerCount = Object.values(runners).filter(Boolean).length;
    const runs = ballInPlayOutcome === "Home Run" ? runnerCount + 1 : ballInPlayOutcome === "Triple" ? Math.min(3, runnerCount + 1) : ballInPlayOutcome === "Double" ? Math.min(2, runnerCount + 1) : runnerCount >= 2 ? 1 : 0;
    if (game.half === "Bottom") metrolinaScore += runs;
    else opponentScore += runs;
    runners = ballInPlayOutcome === "Home Run" ? {} : { first: game.currentBatterId };
  }

  if (outs >= 3) {
    const nextHalf = game.half === "Top" ? "Bottom" : "Top";
    return {
      ...game,
      half: nextHalf,
      inning: game.half === "Bottom" ? game.inning + 1 : game.inning,
      outs: 0,
      balls: 0,
      strikes: 0,
      runners: {},
      metrolinaScore,
      opponentScore,
      currentBatterId: nextBatter(game),
    };
  }

  return {
    ...game,
    outs,
    balls: isStrikeout || isWalk || ballInPlayOutcome ? 0 : balls,
    strikes: isStrikeout || isWalk || ballInPlayOutcome ? 0 : strikes,
    runners,
    metrolinaScore,
    opponentScore,
    currentBatterId: isStrikeout || isWalk || ballInPlayOutcome ? nextBatter(game) : game.currentBatterId,
  };
}

function nextBatter(game: Game): ID | undefined {
  if (!game.lineup.length) return game.currentBatterId;
  const index = game.lineup.findIndex((playerId) => playerId === game.currentBatterId);
  return game.lineup[(index + 1) % game.lineup.length] ?? game.lineup[0];
}

function gameSituations(game: Game, outcome: GamePitchOutcome, bip?: GameBallInPlayOutcome): string[] {
  const situations: string[] = [];
  if (game.balls === 0 && game.strikes === 0) situations.push("First-pitch");
  if (game.strikes === 2) situations.push("Two-strike");
  if (game.outs === 2) situations.push("Two-out");
  if (game.runners.second || game.runners.third) situations.push("RISP");
  if (game.runners.third && game.outs < 2) situations.push("Runner on 3rd <2 outs");
  if (outcome === "In Play" && bip && ["Sac Fly", "Sac Bunt", "Ground Out"].includes(bip)) situations.push("Productive out check");
  if (outcome === "Swinging Strike") situations.push("Whiff");
  return situations;
}

function mapLiveBpOutcome(label: LiveBpOutcomeLabel): NonNullable<PlateAppearance["outcome"]> {
  const outcomes: Record<LiveBpOutcomeLabel, NonNullable<PlateAppearance["outcome"]>> = {
    K: "Strikeout swinging",
    BB: "Walk",
    HBP: "HBP",
    "1B": "Single",
    "2B": "Double",
    "3B": "Triple",
    HR: "Home run",
    Out: "Groundout",
    Error: "Reached on error",
    FC: "Fielder's choice",
  };
  return outcomes[label];
}

function nextCount(count: { balls: number; strikes: number }, outcome: PitchOutcome) {
  let balls = count.balls;
  let strikes = count.strikes;
  if (outcome === "Ball") balls += 1;
  if (outcome === "Called Strike" || outcome === "Whiff") strikes += 1;
  if (outcome === "Foul" && strikes < 2) strikes += 1;
  if (outcome === "Ball in play" || balls >= 4 || strikes >= 3) return { balls: 0, strikes: 0 };
  return { balls, strikes };
}

function nextLiveBpDisplayCount(count: CountState, outcome: PitchOutcome): CountState {
  let balls = count.balls;
  let strikes = count.strikes;
  if (outcome === "Ball") balls += 1;
  if (outcome === "Called Strike" || outcome === "Whiff") strikes += 1;
  if (outcome === "Foul" && strikes < 2) strikes += 1;
  if (outcome === "Ball in play" || outcome === "HBP") return count;
  return { balls: Math.min(3, balls), strikes: Math.min(2, strikes) };
}

function baseLine(game: Game) {
  const bases = [game.runners.first ? "1B" : null, game.runners.second ? "2B" : null, game.runners.third ? "3B" : null].filter(Boolean);
  return bases.length ? bases.join(" / ") : "Bases empty";
}

function positionLine(player: Player) {
  return player.secondaryPosition ? `${player.primaryPosition} / ${player.secondaryPosition}` : player.primaryPosition;
}

function lastName(name: string) {
  return name.split(" ").filter(Boolean).slice(-1)[0] ?? name;
}

function throwingRoleLabel(player: Player) {
  if (player.primaryPosition === "RHP" || player.primaryPosition === "LHP") return player.primaryPosition;
  if (player.secondaryPosition === "RHP" || player.secondaryPosition === "LHP") return player.secondaryPosition;
  if (player.throws === "L") return "LHP";
  if (player.throws === "R") return "RHP";
  return "P";
}

function practiceModeClass(mode: PracticeMode) {
  return mode.toLowerCase().replace(/\s+/g, "-");
}

function practiceModeIcon(mode: PracticeMode) {
  const Icon = mode === "Hitting" ? Swords : mode === "Pitching" ? BaseballIcon : mode === "Defense" ? Shield : Gauge;
  return <Icon size={16} aria-hidden="true" />;
}

function zoneLabel(point: ZonePoint) {
  const column = point.x < 0.34 ? 0 : point.x > 0.66 ? 2 : 1;
  const row = point.y < 0.34 ? 0 : point.y > 0.66 ? 2 : 1;
  return String(row * 3 + column + 1);
}

function derivePlayerRoleFlags(primaryPosition?: Position, secondaryPosition?: Position) {
  const positions = [primaryPosition, secondaryPosition].filter(Boolean);
  return {
    isPitcher: positions.some((position) => position === "P" || position === "RHP" || position === "LHP"),
    isHitter: true,
  };
}

function heightToInches(value?: string) {
  if (!value) return 72;
  const feetInches = value.match(/^(\d+)\s*['-]\s*(\d{1,2})/);
  if (feetInches) return Number(feetInches[1]) * 12 + Number(feetInches[2]);
  const totalInches = value.match(/^(\d{2,3})$/);
  if (totalInches) return Number(totalInches[1]);
  return 72;
}

function formatHeightFromInches(value: number) {
  const safeValue = Math.max(48, Math.min(90, Math.round(value)));
  return `${Math.floor(safeValue / 12)}-${safeValue % 12}`;
}

function buildScheduleItems(data: AppData): ScheduleItem[] {
  const practiceItems: ScheduleItem[] = data.practices.map((practice) => ({
    id: `practice-${practice.id}`,
    source: "practice",
    sourceId: practice.id,
    eventType: "Practice",
    title: practice.name || practice.type,
    startAt: practice.startedAt,
    endAt: practice.endedAt,
    date: practice.date,
    location: practice.location,
    notes: practice.notes,
    visibility: "TEAM_ONLY",
    status: practice.endedAt ? "Completed" : "Scheduled",
    accent: SCHEDULE_EVENT_ACCENTS.Practice,
  }));

  const gameItems: ScheduleItem[] = data.games.map((game) => ({
    id: `game-${game.id}`,
    source: "game",
    sourceId: game.id,
    eventType: "Game",
    title: `${matchupPrefix(game.homeAway).replace(".", "")} ${game.opponent}`,
    startAt: game.startsAt ?? toLocalIso(game.date, "18:00"),
    date: game.date,
    location: game.location,
    notes: game.type,
    visibility: defaultScheduleVisibility("Game", data.teamContext?.currentTeam),
    status: game.result ? "Completed" : "Scheduled",
    accent: SCHEDULE_EVENT_ACCENTS.Game,
  }));

  const workoutsByDate = new Map<string, WorkoutSession[]>();
  for (const session of data.workoutSessions) {
    const dateSessions = workoutsByDate.get(session.date) ?? [];
    dateSessions.push(session);
    workoutsByDate.set(session.date, dateSessions);
  }
  const liftItems: ScheduleItem[] = [...workoutsByDate.entries()].map(([date, sessions]) => ({
    id: `lift-${date}`,
    source: "lift",
    sourceId: sessions[0]?.id ?? date,
    eventType: "Lift",
    title: sessions.length > 1 ? `Team Lift (${sessions.length})` : "Team Lift",
    startAt: toLocalIso(date, "16:00"),
    date,
    location: "Weight Room",
    visibility: "TEAM_ONLY",
    status: sessions.every((session) => session.completed) ? "Completed" : "Scheduled",
    accent: SCHEDULE_EVENT_ACCENTS.Lift,
  }));

  const genericItems: ScheduleItem[] = (data.scheduleEvents ?? [])
    .filter((event) => !event.practiceId && !event.gameId && !event.workoutSessionId)
    .map((event) => ({
      id: `event-${event.id}`,
      source: "event",
      sourceId: event.id,
      eventType: event.eventType,
      title: event.title,
      startAt: event.startAt,
      endAt: event.endAt,
      date: dateKeyFromIso(event.startAt),
      location: event.location,
      notes: event.notes,
      visibility: event.visibility,
      status: event.status,
      accent: SCHEDULE_EVENT_ACCENTS[event.eventType],
    }));

  return [...practiceItems, ...gameItems, ...liftItems, ...genericItems].sort((a, b) => Date.parse(a.startAt) - Date.parse(b.startAt));
}

function toLocalIso(date: string, time = "12:00") {
  const safeTime = time || "12:00";
  return new Date(`${date}T${safeTime}:00`).toISOString();
}

function dateKeyFromIso(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value.slice(0, 10);
  return localDateKey(date);
}

function todayKey() {
  return localDateKey(new Date());
}

function isUpcomingScheduleItem(item: ScheduleItem) {
  return Date.parse(item.startAt) >= Date.parse(`${todayKey()}T00:00:00`);
}

function isPastScheduleItem(item: ScheduleItem) {
  return Date.parse(item.startAt) < Date.parse(`${todayKey()}T00:00:00`);
}

function isoDate(date: Date) {
  return localDateKey(date);
}

function localDateKey(date: Date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function isToday(dateKey: string) {
  return dateKey === todayKey();
}

function calendarDaysForMonth(cursor: Date) {
  const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
  const start = new Date(first);
  const day = start.getDay();
  start.setDate(start.getDate() - (day === 0 ? 6 : day - 1));
  return Array.from({ length: 42 }, (_, index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    return date;
  });
}

function weekDates(cursor: Date) {
  const start = new Date(cursor);
  const day = start.getDay();
  start.setDate(start.getDate() - (day === 0 ? 6 : day - 1));
  return Array.from({ length: 7 }, (_, index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    return date;
  });
}

function weekRangeLabel(cursor: Date) {
  const days = weekDates(cursor);
  const first = days[0];
  const last = days[6];
  return `${first.toLocaleDateString("en-US", { month: "short", day: "numeric" })} - ${last.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
}

function monthCursor(dateKey?: string) {
  const date = parseDateKey(dateKey) ?? new Date();
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

function parseDateKey(dateKey?: string) {
  if (!dateKey) return undefined;
  const [year, month, day] = dateKey.split("-").map(Number);
  if (!year || !month || !day) return undefined;
  return new Date(year, month - 1, day);
}

function formatPickerDate(dateKey?: string) {
  const date = parseDateKey(dateKey);
  if (!date) return "Select date";
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function parseTimeValue(value?: string) {
  if (!value) return undefined;
  const match = value.match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return undefined;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) return undefined;
  return hours * 60 + minutes;
}

function formatMinutesAsTimeValue(totalMinutes: number) {
  const normalized = ((totalMinutes % 1440) + 1440) % 1440;
  const hours = Math.floor(normalized / 60);
  const minutes = normalized % 60;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function formatPickerTime(value?: string) {
  const minutes = parseTimeValue(value);
  if (minutes === undefined) return "";
  const hours = Math.floor(minutes / 60);
  const minutePart = minutes % 60;
  const hour12 = hours % 12 || 12;
  const period = hours >= 12 ? "PM" : "AM";
  return `${hour12}:${String(minutePart).padStart(2, "0")} ${period}`;
}

function timePickerParts(value?: string): { hour: number; minute: number; period: TimePeriod } {
  const totalMinutes = parseTimeValue(value) ?? 18 * 60;
  const hours = Math.floor(totalMinutes / 60);
  const minute = totalMinutes % 60;
  return {
    hour: hours % 12 || 12,
    minute,
    period: hours >= 12 ? "PM" : "AM",
  };
}

function timeValueFromParts(parts: { hour: number; minute: number; period: TimePeriod }) {
  let hour = clampNumber(parts.hour, 1, 12);
  const minute = clampNumber(parts.minute, 0, 59);
  if (parts.period === "AM" && hour === 12) hour = 0;
  if (parts.period === "PM" && hour !== 12) hour += 12;
  return formatMinutesAsTimeValue(hour * 60 + minute);
}

function parseTimeInput(value: string) {
  const normalized = value.trim().toLowerCase();
  if (!normalized) return "";
  const match = normalized.match(/^(\d{1,2})(?::?(\d{2}))?\s*(a|am|p|pm)?$/);
  if (!match) return undefined;
  let hours = Number(match[1]);
  const minutes = Number(match[2] ?? "0");
  const period = match[3];
  if (minutes > 59 || hours > 24) return undefined;
  if (period) {
    if (hours < 1 || hours > 12) return undefined;
    if (period.startsWith("p") && hours !== 12) hours += 12;
    if (period.startsWith("a") && hours === 12) hours = 0;
  } else if (hours === 24) {
    hours = 0;
  }
  return formatMinutesAsTimeValue(hours * 60 + minutes);
}

function defaultEndTime(startTime: string) {
  const startMinutes = parseTimeValue(startTime);
  if (startMinutes === undefined) return "19:00";
  return formatMinutesAsTimeValue(startMinutes + 60);
}

function groupScheduleItemsByDate(items: ScheduleItem[]) {
  const groups = new Map<string, ScheduleItem[]>();
  for (const item of items) {
    const group = groups.get(item.date) ?? [];
    group.push(item);
    groups.set(item.date, group);
  }
  return [...groups.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([date, groupItems]) => ({
      date,
      items: groupItems.sort((a, b) => Date.parse(a.startAt) - Date.parse(b.startAt)),
    }));
}

function agendaDateLabel(date: string) {
  const today = todayKey();
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowKey = tomorrow.toISOString().slice(0, 10);
  if (date === today) return "Today";
  if (date === tomorrowKey) return "Tomorrow";
  return fullDate(date);
}

function teamContextLine(team?: TeamOption) {
  if (!team) return "Current team";
  return `${team.teamName} - ${team.seasonName ?? "Current season"}`;
}

function defaultScheduleVisibility(type: ScheduleEventType, team?: TeamOption): ScheduleEventVisibility {
  void team;
  if (type === "Game" || type === "Tournament") return "PUBLIC";
  return "TEAM_ONLY";
}

function matchupPrefix(homeAway: Game["homeAway"]) {
  return homeAway === "Away" ? "at" : "vs.";
}

function defaultScheduleTitle(type: ScheduleEventType, opponent = "", homeAway: Game["homeAway"] = "Home") {
  const trimmedOpponent = opponent.trim();
  if (type === "Practice") return "Practice";
  if (type === "Game") return trimmedOpponent ? `${matchupPrefix(homeAway)} ${trimmedOpponent}` : "Game";
  if (type === "Lift") return "Team Lift";
  if (type === "Scrimmage") return trimmedOpponent === "Intersquad" ? "Intersquad Scrimmage" : trimmedOpponent ? `${matchupPrefix(homeAway)} ${trimmedOpponent} Scrimmage` : "Scrimmage";
  if (type === "Meeting") return "Team Meeting";
  if (type === "Team Event") return "Team Event";
  if (type === "Tournament") return "Tournament";
  return "Other";
}

function isDefaultScheduleTitle(title: string) {
  const normalized = title.trim();
  if (!normalized) return true;
  return SCHEDULE_EVENT_TYPES.some((type) => normalized === defaultScheduleTitle(type));
}

function shouldResetScheduleTitle(nextType: ScheduleEventType, currentTitle: string) {
  if (nextType === "Practice" || nextType === "Lift") return true;
  return isDefaultScheduleTitle(currentTitle);
}

function formatCompactNumber(value: number) {
  return new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: value >= 1000 ? 1 : 0 }).format(value);
}

function clampNumber(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value));
}

function formatTime(value?: string) {
  if (!value) return "--";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
}

function formatPracticeStartTime(practice: Practice) {
  return formatTime(practice.startedAt);
}

function formatPracticeTimeRange(practice: Practice) {
  const start = formatTime(practice.startedAt);
  if (practice.endedAt) return `${start}-${formatTime(practice.endedAt)}`;
  return start;
}

function sortPlayersByRecent(players: Player[], recentIds: ID[]) {
  return players.slice().sort((a, b) => {
    const recentA = recentIds.indexOf(a.id);
    const recentB = recentIds.indexOf(b.id);
    if (recentA !== recentB) return (recentA === -1 ? 999 : recentA) - (recentB === -1 ? 999 : recentB);
    return a.jerseyNumber - b.jerseyNumber;
  });
}

function formatSegment(value: string) {
  if (value === "overview") return "Overview";
  if (value === "box-score") return "Box Score";
  if (value === "situational") return "Situational";
  if (value === "all") return "All";
  if (value === "live-bp") return "Live BP";
  if (value === "weight-room") return "Weight Room";
  if (value === "attendance") return "Attendance";
  if (value === "trends") return "Trends";
  if (value === "practice") return "Practice";
  if (value === "games") return "Games";
  if (value === "pitching") return "Pitching";
  if (value === "hitting") return "Hitting";
  if (value === "defense") return "Defense";
  if (value === "development") return "Development";
  if (value === "weights") return "Weight Room";
  if (value === "notes") return "Notes";
  return value.split(/[-_]/).filter(Boolean).map((segment) => `${segment.slice(0, 1).toUpperCase()}${segment.slice(1)}`).join(" ");
}

function weekStart(dateString: string) {
  const date = new Date(`${dateString}T12:00:00`);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1);
  date.setDate(diff);
  return date.toISOString().slice(0, 10);
}

function weekdayName(dateString: string): WorkoutSession["day"] {
  const names: WorkoutSession["day"][] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  return names[new Date(`${dateString}T12:00:00`).getDay()] ?? "Mon";
}

function suggestTeamForFile(file: ParsedRosterFile, teams: TeamOption[], fallback?: TeamOption) {
  const haystack = `${file.fileName} ${file.detectedTeamName ?? ""}`.toLowerCase();
  const direct = teams.find((team) => haystack.includes(team.teamName.toLowerCase()));
  if (direct) return direct;
  if (haystack.includes("varsity")) return teams.find((team) => /varsity/i.test(team.teamName)) ?? fallback;
  if (/\bjv\b|junior varsity/.test(haystack)) return teams.find((team) => /\bjv\b|junior varsity/i.test(team.teamName)) ?? fallback;
  return fallback;
}

function teamLevelFromName(teamName: string) {
  const value = teamName.toLowerCase();
  if (value.includes("varsity")) return "Varsity";
  if (/\bjv\b|junior varsity/.test(value)) return "JV";
  const travel = value.match(/\b(1[3-9]u)\b/i);
  return travel ? travel[1].toUpperCase() : "";
}

function teamValue(team?: TeamOption) {
  return team ? `${team.teamId}:${team.seasonId ?? "all"}` : "";
}

function profileTeamPinMatchesTeam(pin: ProfileTeamPin, team: TeamOption) {
  return pin.teamId === team.teamId && (pin.seasonId ?? "") === (team.seasonId ?? "");
}

function isPinnedTeam(pins: ProfileTeamPin[] | undefined, team: TeamOption) {
  return Boolean(pins?.some((pin) => profileTeamPinMatchesTeam(pin, team)));
}

function pinnedTeamsFromContext(context?: TeamContext, pins: ProfileTeamPin[] = []) {
  const teams = displayWorkspaceTeams(context?.availableTeams ?? []);
  const teamsByValue = new Map(teams.map((team) => [teamValue(team), team]));
  return pins
    .map((pin) => teamsByValue.get(`${pin.teamId}:${pin.seasonId ?? "all"}`))
    .filter((team): team is TeamOption => Boolean(team))
    .slice(0, 3);
}

function teamOrganizationLogo(team: TeamOption, context?: TeamContext) {
  return context?.organizations?.find((organization) => organization.id === team.organizationId)?.logoUrl;
}

function isFollowingTeam(follows: ProfileFollow[] | undefined, teamId: ID) {
  return Boolean(follows?.some((follow) => follow.teamId === teamId));
}

function isFollowingOrganization(follows: ProfileFollow[] | undefined, organizationId: ID) {
  return Boolean(follows?.some((follow) => follow.organizationId === organizationId && !follow.teamId));
}

function followedPublicTeams(data: AppData) {
  const managedTeamIds = new Set((data.teamContext?.availableTeams ?? []).map((team) => team.teamId));
  const follows = data.profileFollows ?? [];
  const followedTeamIds = new Set(follows.map((follow) => follow.teamId).filter((teamId): teamId is ID => Boolean(teamId)));
  return (data.publicTeams ?? []).filter((team) => followedTeamIds.has(team.id) && !managedTeamIds.has(team.id));
}

function followedPublicOrganizations(data: AppData) {
  const follows = data.profileFollows ?? [];
  const followedOrganizationIds = new Set(
    follows
      .filter((follow) => follow.organizationId && !follow.teamId)
      .map((follow) => follow.organizationId)
      .filter((organizationId): organizationId is ID => Boolean(organizationId)),
  );
  return (data.publicOrganizations ?? []).filter((organization) => followedOrganizationIds.has(organization.id));
}

function organizationLocation(source: { city?: string; state?: string }) {
  return [source.city, source.state].filter(Boolean).join(", ");
}

function publicOrganizationSearchText(organization: PublicDirectoryOrganizationSummary) {
  return [
    organization.name,
    organization.city,
    organization.state,
    organization.teams.map((team) => `${team.name} ${team.level ?? ""} ${team.seasonName ?? ""}`).join(" "),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function publicTeamSearchText(team: PublicDirectoryTeamSummary) {
  return [team.organizationName, team.name, team.level, team.seasonName, team.city, team.state]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function roleLabel(role?: string) {
  return (role ?? "STAFF")
    .toLowerCase()
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function profileDisplayName(context?: TeamContext) {
  const profile = context?.profile;
  const named = [profile?.firstName, profile?.lastName].filter(Boolean).join(" ").trim();
  const display = profile?.displayName && !profile.displayName.includes("@") ? profile.displayName : "";
  return named || display || profile?.email?.split("@")[0]?.replace(/[._-]+/g, " ") || "Coach";
}

function preferredProfileDisplayName(profile?: AppProfile) {
  const named = [profile?.firstName, profile?.lastName].filter(Boolean).join(" ").trim();
  const display = profile?.displayName && !profile.displayName.includes("@") ? profile.displayName : "";
  return display || named || profile?.email?.split("@")[0]?.replace(/[._-]+/g, " ") || "Coach";
}

function gradeSession(note: string) {
  return note.length > 80 ? "A-" : note.length > 20 ? "B+" : "B";
}

function distanceBetween(a: ZonePoint, b: ZonePoint) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function isZonePoint(point: ZonePoint | undefined): point is ZonePoint {
  return Boolean(point && Number.isFinite(point.x) && Number.isFinite(point.y));
}
